comms.text:
@1 אִלֵן תּוּלְדַת נֹחַ נֹחַ גְּבַר זַכַּאי שְׁלִים הֲוָה בְּדָרוֹהִי בְּדַחַלְתָּא דַּיְיָ הַלִּיךְ נֹחַ:
@2 וְאוֹלִיד נֹחַ תְּלָתָא בְנִין יָת שֵׁם יָת חָם וְיָת יָפֶת:
@3 וְאִתְחַבָּלַת אַרְעָא קֳדָם יְיָ וְאִתְמְלִיאַת אַרְעָא חֲטּוֹפִין:
@4 וַחֲזָא יְיָ יָת אַרְעָא וְהָא אִתְחַבָּלַת אֲרֵי חַבִּילוּ כָּל בִּסְרָא אֱנַשׁ יָת אָרְחֵהּ עַל אַרְעָא:
@5 וַאֲמַר יְיָ לְנֹחַ קִצָא דְכָל בִּסְרָא עַלַּת לִקֳדָמַי אֲרֵי אִתְמְלִיאַת אַרְעָא חֲטוֹפִין מִן קֳדָם עוֹבָדֵיהוֹן בִּישַׁיָּא וְהָא אֲנָא מְחַבֶּלְהוֹן עִם אַרְעָא:
@6 עִבֵד לָךְ תֵּבוֹתָא דְאָעִין דְּקַדְרוֹם מְדוֹרִין תַּעְבֵּד יָת תֵּבוֹתָא וְתֶחְפֵּי יָתַהּ מִגָּו וּמִבָּרָא בְּכּוּפְרָא:
@7 וְדֵין דְּתַעְבֵּד יָתַהּ תְּלַת מְאָה אַמִּין אֻרְכָּא דְתֵבוֹתָא חַמְשִׁין אַמִּין פְּתָיַהּ וּתְלָתִין אַמִּין רוּמַהּ:
@8 נֵהוֹר תַּעְבֵּיד לְתֵבוֹתָא וּלְאַמְתָא תְּשַׁכְלְלִינַהּ מִלְּעֵלָּא וְתַרְעָא דְתֵבוֹתָא בְּסִטְרַהּ תְּשַׁוִּי מְדוֹרִין אֲרָעִין תִּנְיָנִין וּתְלִיתָאִין תַּעְבְּדִנַּהּ:
@9 וַאֲנָא הָא אֲנָא מַיְתֵי יָת טוֹפָנָא מַיָּא עַל אַרְעָא לְחַבָּלָא כָּל בִּסְרָא דִּי בֵהּ רוּחָא דְחַיֵּי מִתְּחוֹת שְׁמַיָּא כֹּל דִּי בְאַרְעָא יְמוּת:
@10 וְאָקֵם יָת קְיָמִי עִמָּךְ וְתֵעוֹל לְתֵבוֹתָא אַתְּ וּבְנָךְ וְאִתְּתָךְ וּנְשֵׁי בְנָיךְ עִמָּךְ:
@11 וּמִכָּל דְּחַי מִכָּל בִּסְרָא תְּרֵין מִכֹּלָּא תָּעֵיל לְתֵבוֹתָא לְקַיָּמָא עִמָּךְ דְּכַר וְנוּקְבָא יְהוֹן:
@12 מֵעוֹפָא לִזְנוֹהִי וּמִן בְּעִירָא לִזְנַהּ וּמִכֹּל רִחֲשָׁא דְאַרְעָא לִזְנוֹהִי תְּרֵין מִכֹּלָּא יַעֲלוּן לְוָתָךְ לְקַיָּמָא:
@13 וְאַתְּ סַב לָךְ מִכָּל מֵיכַל דְּמִתְאֲכֵל וְתִכְנוֹשׁ לְוָתָךְ וִיהֵי לָךְ וּלְהוֹן לְמֵיכָל:
@14 וַעֲבַד נֹחַ כְּכֹל דִּי פַקֵּיד יָתֵהּ יְיָ כֵּן עֲבָד:
@15 וַאֲמַר יְיָ לְנֹחַ עוּל אַתְּ וְכָל אֱנַשׁ בֵּיתָךְ לְתֵבוֹתָא אֲרֵי יָתָךְ חֲזֵיתִי זַכַּאי קֳדָמַי בְּדָרָא הָדֵין:
@16 מִכֹּל בְּעִירָא דַכְיָא תִּסַּב לָךְ שַׁבְעָא שַׁבְעָא דְּכַר וְנוּקְבָא וּמִן בְּעִירָא דְּלָא אִיתָהָא דַכְיָא הִיא תְּרֵין דְּכַר וְנוּקְבָא:
@17 אַף מֵעוֹפָא דִשְׁמַיָּא שַׁבְעָא שַׁבְעָא דְּכַר וְנוּקְבָא לְקַיָּמָא זַרְעָא עַל אַפֵּי כָל אַרְעָא:
@18 אֲרֵי לִזְמַן יוֹמִין עוֹד שַׁבְעָא אֲנָא מָחֵת מִטְרָא עַל אַרְעָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְאֶמְחֵי יָת כָּל יְקוּמָא דִּי עַבְדֵת מֵעַל אַפֵּי אַרְעָא:
@19 וַעֲבַד נֹחַ כְּכֹל דִּי פַקְּדֵהּ יְיָ:
@20 וְנֹחַ בַּר שִׁתְּ מְאָה שְׁנִין וְטּוֹפָנָא הֲוָה מַיָּא עַל אַרְעָא:
@21 וְעָאל נֹחַ וּבְנוֹהִי וְאִתְּתֵהּ וּנְשֵׁי בְנוֹהִי עִמֵּהּ לְתֵבוֹתָא מִן קֳדָם מֵי טוֹפָנָא:
@22 מִן בְּעִירָא דַּכְיָא וּמִן בְּעִירָא דִּי לֵיתָהָא דַּכְיָא וּמִן עוֹפָא וְכֹל דִּי רָחֵשׁ עַל אַרְעָא:
@23 תְּרֵין תְּרֵין עַלּוּ לְוַת נֹחַ לְתֵבוֹתָא דְּכַר וְנוּקְבָא כְּמָא דִּי פַּקֵּיד יְיָ יָת נֹחַ:
@24 וַהֲוָה לִזְמַן שִׁבְעַת יוֹמִין וּמֵי טוֹפָנָא הֲווֹ עַל אַרְעָא:
@25 בִּשְׁנַת שִׁתְּ מְאָה שְׁנִין לְחַיֵּי נֹחַ בְּיַרְחָא תִּנְיָנָא בְּשִׁבְעַת עַשְׂרָא יוֹמָא לְיַרְחָא בְּיוֹמָא הָדֵין אִתְבְּזָעוּ כָּל מַבּוּעֵי תְּהוֹמָא רַבָּא וְכַוֵּי שְׁמַיָּא אִתְפַּתָּחוּ:
@26 וַהֲוָה מִטְרָא נָחֵת עַל אַרְעָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן:
@27 בִּכְרַן יוֹמָא הָדֵין עָאל נֹחַ וְשֵׁם וְחָם וָיֶפֶת בְּנֵי נֹחַ וְאִתַּת נֹחַ וּתְלָתָא נְשֵׁי בְנוֹהִי עִמְהוֹן לְתֵבוֹתָא:
@28 אִנּוּן וְכָל חַיְתָא לִזְנַהּ וְכָל בְּעִירָא לְזְנַהּ וְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא לִזְנוֹהִי וְכָל עוֹפָא לִזְנוֹהִי כֹּל צִפַּר כָּל דְּפָרָח:
@29 וְעַלּוּ עִם נֹחַ לְתֵבוֹתָא תְּרֵין תְּרֵין מִכָּל בִּשְׂרָא דִּי בֵהּ רוּחָא דְּחַיֵּי:
@30 וְעָלַיָּא דְּכַר וְנוּקְבָא מִכָּל בִּשְׂרָא עַלּוּ כְּמָא דִּי פַּקֵּיד יָתֵהּ יְיָ וַאֲגֵן יְיָ (בְּמֵימְרֵהּ) עֲלוֹהִי:
@31 וַהֲוָה טוֹפָנָא אַרְבְּעִין יְמָמִין עַל אַרְעָא וּסְגִיאוּ מַיָּא וּנְטָלוּ יָת תֵּבוֹתָא וְאִתָּרָמַת מֵעַל אַרְעָא:
@32 וּתְקִיפוּ מַיָּא וּסְגִיאוּ לַחֲדָא עַל אַרְעָא וּמְהַלְּכָא תֵבוֹתָא עַל אַפֵּי מַיָּא:
@33 וּמַיָּא תְּקִיפוּ לַחֲדָא לַחֲדָא עַל אַרְעָא וְאִתְחֲפִיאוּ כָּל טוּרַיָּא רָמַיָּא דִּי תְחוֹת כָּל שְׁמַיָּא:
@34 חֲמֵשׁ עַשְׂרֵי אַמִּין מִלְעֵלָּא תְּקִיפוּ מַיָּא וְאִתְחֲפִיאוּ טוּרַיָּא:
@35 וּמִית כָּל בִּשְׂרָא דְּרָחֵשׁ עַל אַרְעָא בְּעוֹפָא וּבִבְעִירָא וּבְחַיְתָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא וְכֹל אֱנָשָׁא:
@36 כֹּל דִּי נִשְׁמְתָא רוּחָא דְּחַיִּין בְּאַפּוֹהִי מִכֹּל דִּי בְּיַבֶּשְׁתָּא מִיתוּ:
@37 וּמְחָא יָת כָּל יְקוּמָא דִּי עַל אַפֵּי אַרְעָא מֵאֱנָשָׁא עַד בְּעִירָא עַד רִחֲשָׁא וְעַד עוֹפָא דִּשְׁמַיָּא וְאִתְמְחִיאוּ מִן אַרְעָא וְאִשְׁתָּאַר בְּרַם נֹחַ וְדִי עִמֵּהּ בְּתֵבוֹתָא:
@38 וּתְקִיפוּ מַיָּא עַל אַרְעָא מְאָה וְחַמְשִׁין יוֹמִין:
@39 וּדְכִיר יְיָ יָת נֹחַ וְיָת כָּל חַיְתָא וְיָת כָּל בְּעִירָא דִּי עִמֵּהּ בְּתֵבוֹתָא וְאַעְבַּר יְיָ רוּחָא עַל אַרְעָא וְנָחוּ מַיָּא:
@40 וְאִסְתְּכָרוּ מַבּוּעֵי תְהוֹמָא וְכַוֵּי שְׁמַיָּא וְאִתְכְּלִי מִטְרָא מִן שְׁמַיָּא:
@41 וְתָבוּ מַיָּא מֵעַל אַרְעָא אָזְלִין וְתָיְבִין וַחֲסָרוּ מַיָּא מִסּוֹף מְאָה וְחַמְשִׁין יוֹמִין:
@42 וְנָחַת תֵּבוֹתָא בְּיַרְחָא שְׁבִיעָאָה בְּשִׁבְעַת עֲשַׂר יוֹמָא לְיַרְחָא עַל טוּרֵי קַרְדּוּ:
@43 וּמַיָּא הֲווֹ אָזְלִין וְחָסְרִין עַד יַרְחָא עֲשִׂירָאָה בַּעֲשִׂירָאָה בְּחַד לְיַרְחָא אִתְחֲזִיאוּ רֵישֵׁי טוּרַיָּא:
@44 וַהֲוָה מִסּוֹף אַרְבְּעִין יוֹמִין וּפְתַח נֹחַ יָת כַּוַּת תֵּבוֹתָא דִּי עֲבָד:
@45 וְשַׁלַּח יָת עוֹרְבָא וּנְפַק מִפַּק וְתַיִּב עַד דְּיַבִּישׁוּ מַיָּא מֵעַל אַרְעָא:
@46 וְשַׁלַּח יָת יוֹנָה מִלְּוָתֵהּ לְמֵחֲזֵי הֲקַלִּיאוּ מַיָּא מֵעַל אַפֵּי אַרְעָא:
@47 וְלָא אַשְׁכַּחַת יוֹנָה מְנַח לְפַרְסַת רַגְלַהּ וְתָבַת לְוָתֵהּ לְתֵבוֹתָא אֲרֵי מַיָּא עַל אַפֵּי כָל אַרְעָא וְאוֹשִׁיט יְדֵהּ וְנָסְבַהּ וְאָעֵיל יָתַהּ לְוָתֵהּ לְתֵבוֹתָא:
@48 וְאוֹרִיךְ עוֹד שַׁבְעָא יוֹמִין אָחֳרָנִין וְאוֹסֵיף שַׁלַּח יָת יוֹנָה מִן תֵּבוֹתָא:
@49 וַאֲתַת לְוָתֵהּ יוֹנָה לְעִדַּן רַמְשָׁא וְהָא טְּרַף זֵיתָא תְּבִיר נָחִית בְּפוּמַהּ וִידַע נֹחַ אֲרֵי קַלִּיאוּ מַיָּא מֵעַל אַרְעָא:
@50 וְאוֹרִיךְ עוֹד שַׁבְעָא יוֹמִין אָחֳרָנִין וְשַׁלַּח יָת יוֹנָה וְלָא אוֹסֵיפַת לְמִתּוּב לְוָתֵהּ עוֹד:
@51 וַהֲוָה בְּשִׁתְּ מְאָה וְחַד שְׁנִין בְּקַדְמָאָה בְּחַד לְיַרְחָא נְגוּבוּ מַיָּא מֵעַל אַרְעָא וְאַעְדִּי נֹחַ יָת חוֹפָאָה דְּתֵבוֹתָא וַחֲזָא וְהָא נְגוּבוּ אַפֵּי אַרְעָא:
@52 וּבְיַרְחָא תִּנְיָנָא בְּעַשְׂרִין וְשַׁבְעָא יוֹמָא לְיַרְחָא יַבִּישַׁת אַרְעָא:
@53 וּמַלִּיל יְיָ עִם נֹחַ לְמֵימָר:
@54 פּוּק מִן תֵּבוֹתָא אַתְּ וְאִתְּתָךְ וּבְנָךְ וּנְשֵׁי בְנָיךְ עִמָךְ:
@55 כָּל חַיְתָא דְּעִמָּךְ מִכָּל בִּשְׂרָא בְּעוֹפָא וּבִבְעִירָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא אַפֵּיק עִמָּךְ וְיִתְיַלְּדוּן בְּאַרְעָא וְיִפְּשׁוּן וְיִסְגּוּן עַל אַרְעָא:
@56 וּנְפַק נֹחַ וּבְנוֹהִי וְאִתְּתֵהּ וּנְשֵׁי בְנוֹהִי עִמֵּהּ:
@57 כָּל חַיְתָא כָּל רִחֲשָׁא וְכָל עוֹפָא כֹּל דְּרָחֵשׁ עַל אַרְעָא לְזַרְעֲיָתְהוֹן נְפָקוּ מִן תֵּבוֹתָא:
@58 וּבְנָא נֹחַ מַדְבְּחָא קֳדָם יְיָ וּנְסִיב מִכֹּל בְּעִירָא דַּכְיָא וּמִכֹּל עוֹפָא דְכֵי וְאַסֵּיק עֲלָוָן בְּמִדְבְּחָא:
@59 וְקַבִּיל יְיָ בְּרַעֲוָא יָת קוּרְבָּנֵהּ וַאֲמַר יְיָ בְּמֵימְרֵהּ לָא אוֹסֵף לְמֵילַט עוֹד יָת אַרְעָא בְּדִיל חוֹבֵי אֱנָשָׁא אֲרֵי יִצְרָא לִבָּא דֶּאֱנָשָׁא בִּישׁ מִזְעִירֵהּ וְלָא אוֹסֵף עוֹד לְמִמְחֵי יָת כָּל דְּחַי כְּמָא דִעַבָדִית:
@60 עוֹד כָּל יוֹמֵי אַרְעָא זְרוֹעָא וַחֲצָדָא וְקוֹרָא וְחוֹמָא וְקַיְטָא וְסִתְוָא וִימָם וְלֵילְיָא לָא יִבְטְּלוּן:
@61 וּבָרִיךְ יְיָ יָת נֹחַ וְיָת בְּנוֹהִי וַאֲמַר לְהוֹן פּוּשׁוּ וּסְגוּ וּמְלוּ יָת אַרְעָא:
@62 וְדַחֲלַתְכוֹן וְאֵימַתְכוֹן תְּהֵי עַל כָּל חֵוַת אַרְעָא וְעַל כָּל עוֹפָא דִּשְׁמַיָּא בְּכֹל דִּי תַרְחֵישׁ אַרְעָא וּבְכָל נוּנֵי יַמָּא בְּיֶדְכוֹן יְהוֹן מְסִירִין:
@63 כָּל רִחֲשָׁא דְּהוּא חַי לְכוֹן יְהֵי לְמֵיכָל כִּירוֹק עִשְׂבָּא יְהָבִית לְכוֹן יָת כֹּלָּא:
@64 בְּרַם בִּשְׂרָא בְּנַפְשֵׁהּ דְּמֵהּ לָא תֵכְלוּן:
@65 וּבְרַם יָת דִּמְכוֹן לְנַפְשָׁתֵיכוֹן אֶתְבַּע מִיַּד כָּל חַיְתָא אֶתְבְּעִנֵהּ וּמִיַד אֱנָשָׁא מִיַד גְבַר דְיֵשׁוֹד יָת דְמָא דַאֲחוֹהִי אֶתְבַּע יָת נַפְשָׁא דֶאֱנָשָׁא:
@66 דְיֵשׁוֹד דְמָא דֶאֱנָשָׁא בְּסַעֲדִין עַל מֵימַר דַיָנַיָא דְמֵהּ יִתְּשָׁד אֲרֵי בְּצַלְמָא דַיְיָ עֲבַד יָת אֱנָשָׁא:
@67 וְאַתּוּן פּוּשׁוּ וּסְגוּ אִתְיְלִידוּ בְאַרְעָא וּסְגוּ בַהּ:
@68 וַאֲמַר יְיָ לְנֹחַ וְלִבְנוֹהִי עִמֵּהּ לְמֵימָר:
@69 וַאֲנָא הָא אֲנָא מֵקִים יָת קְיָמִי עִמְּכוֹן וְעִם בְּנֵיכוֹן בַּתְרֵיכוֹן:
@70 וְעִם כָּל נַפְשָׁא חַיְתָא דְּעִמְּכוֹן בְּעוֹפָא בִבְעִירָא וּבְכָל חַיַת אַרְעָא דְּעִמְּכוֹן מִכֹּל נַפְקֵי תֵבוֹתָא לְכֹל חַיַת אַרְעָא:
@71 וְאָקֵם יָת קְיָמִי עִמְּכוֹן וְלָא יִשְׁתֵּיצֵי כָל בִּשְׂרָא עוֹד מִמֵּי טוֹפָנָא וְלָא יְהֵי עוֹד טוֹפָנָא לְחַבָּלָא אַרְעָא:
@72 וַאֲמַר יְיָ דָּא אָת קְיָם דִּי אֲנָא יָהֵב בֵּין מֵימְרִי וּבֵינֵכוֹן וּבֵין כָּל נַפְשָׁא חַיְתָא דִּי עִמְּכוֹן לְדָרֵי עַלְמָא:
@73 יָת קַשְׁתִּי יְהָבִית בַּעֲנָנָא וּתְהִי לְאָת קְיָם בֵּין מֵימְרִי וּבֵין אַרְעָא:
@74 וִיהִי בַּעֲנָנוּתִי עֲנָנָא עַל אַרְעָא וְתִתְחֲזֵי קַשְׁתָּא בַּעֲנָנָא:
@75 וְדָכִירְנָא יָת קְיָמִי דִּי בֵין מֵימְרִי וּבֵינֵיכוֹן וּבֵין כָּל נַפְשָׁא חַיְתָא בְּכָל בִּשְׂרָא וְלָא יְהֵי עוֹד מַיָּא לְטוֹפָנָא לְחַבָּלָא כָל בִּשְׂרָא:
@76 וּתְהֵי קַשְׁתָּא בַּעֲנָנָא וְאֵחֲזִנַּהּ לְמִדְכַּר קְיַם עָלָם בֵּין מֵימְרָא דַּיְיָ וּבֵין כָּל נַפְשָׁא חַיְתָא בְּכָל בִּשְׂרָא דִּי עַל אַרְעָא:
@77 וַאֲמַר יְיָ לְנֹחַ דָּא אָת קְיָם דִּי אֲקֵמִית בֵּין מֵימְרִי וּבֵין כָּל בִּשְׂרָא דִּי עַל אַרְעָא:
@78 וַהֲווֹ בְנֵי נֹחַ דִּי נְפָקוּ מִן תֵּבוֹתָא שֵׁם וְחָם וָיָפֶת וְחָם הוּא אֲבוּהִי דִכְנָעַן:
@79 תְּלָתָא אִלֵּין בְּנֵי נֹחַ וּמֵאִלֵּין אִתְבַּדָּרוּ כָּל אַרְעָא:
@80 וְשָׁרִי נֹחַ גְּבַר פָּלַח בְּאַרְעָא וּנְצִיב כַּרְמָא:
@81 וּשְׁתִי מִן חַמְרָא וּרְוִי וְאִתְגְּלִי בְּגוֹ מַשְׁכְּנֵהּ:
@82 וַחֲזָא חָם אֲבוּהִי דִּכְנַעַן יָת עֶרְיְתָא דַּאֲבוּהִי וְחַוֵּי לִתְרֵין אֲחוֹהִי בְּשׁוּקָא:
@83 וּנְסֵיב שֵׁם וָיֶפֶת יָת כְּסוּתָא וְשַׁוִּיוּ עַל כְּתַף תַּרְוֵיהוֹן וַאֲזָלוּ מְחַזְרִין וַחֲפִיאוּ יָת עֶרְיְתָא דַּאֲבוּהוֹן וְאַפֵּיהוֹן מְחַזְרִין וְעֶרְיְתָא דַּאֲבוּהוֹן לָא חֲזוֹ:
@84 וְאִתְּעַר נֹחַ מֵחַמְרֵהּ וִידַע יָת דִּי עֲבַד לֵהּ בְּרֵהּ זְעֵירָא:
@85 וַאֲמַר לִיט כְּנַעַן עֲבַד פְּלַח עַבְדִין יְהֵי לַאֲחוֹהִי:
@86 וַאֲמַר בְּרִיךְ יְיָ אֱלָהֵהּ דְּשֵׁם וִיהֵי כְנַעַן עַבְדָא לְהוֹן:
@87 יַפְתֵּי יְיָ לְיֶפֶת וְיִשְׁרֵי שְׁכִינְתֵּהּ בְּמַשְׁכְּנֵהּ דְּשֵׁם וִיהֵי כְנַעַן עַבְדָא לְהוֹן:
@88 וַחֲיָא נֹחַ בָּתַר טוֹפָנָא תְּלַת מְאָה וְחַמְשִׁין שְׁנִין:
@89 וַהֲווֹ כָל יוֹמֵי נֹחַ תְּשַׁע מְאָה וְחַמְשִׁין שְׁנִין וּמִית:
@90 וְאִלֵּין תּוּלְדַת בְּנֵי נֹחַ שֵׁם חָם וָיָפֶת וְאִתְיְלִידוּ לְהוֹן בְּנִין בָּתַר טוֹפָנָא:
@91 בְּנֵי יֶפֶת גּוֹמֶר וּמָגוֹג וּמָדַי וְיָוָן וְתוּבָל וּמֶשֶׁךְ וְתִירָס:
@92 וּבְנֵי גּוֹמֶר אַשְׁכְּנַז וְרִיפַת וְתוֹגַרְמָה:
@93 וּבְנֵי יָוָן אֱלִישָׁה וְתַרְשִׁישׁ כִּתִּים וְדֹדָנִים:
@94 מֵאִלֵּין אִתַּפְרָשׁוּ נַגְוַת עַמְמַיָּא בְּאַרְעֲהוֹן גְּבַר לְלִישָׁנֵהּ לְזַרְעֲיָתְהוֹן בְּעַמְמֵיהוֹן:
@95 וּבְנֵי חָם כּוּשׁ וּמִצְרַיִם וּפוּט וּכְנָעַן:
@96 וּבְנֵי כוּשׁ סְבָא וַחֲוִילָה וְסַבְתָּה וְרַעְמָה וְסַבְתְּכָא וּבְנֵי רַעְמָה שְׁבָא וּדְדָן:
@97 וְכוּשׁ אוֹלִיד יָת נִמְרֹד הוּא שָׁרֵי לְמֵהֲוֵי גִבַּר תַּקִּיף בְּאַרְעָא:
@98 הוּא הֲוָה גִבַּר תַּקִּיף קֳדָם יְיָ עַל כֵּן יִתְאֲמַר כְּנִמְרֹד גִּבַּר תַּקִּיף קֳדָם יְיָ:
@99 וַהֲוָה רֵישׁ מַלְכוּתֵהּ בָּבֶל וְאֶרֶךְ וְאַכַּד וְכַלְנֵה בְּאַרְעָא דְּבָבֶל:
@100 מִן אַרְעָא (ס''א עֵיצָה) הַהִיא נְפַק אֲתוּרָאָה וּבְנָא יָת נִינְוֵה וְיָת רְחֹבֹת (נ''א רְחוֹבֵי) קַרְתָּא וְיָת כָּלַח:
@101 וְיָת רֶסֶן בֵּין נִינְוֵה וּבֵין כָּלַח הִיא קַרְתָּא רַבְּתָא:
@102 וּמִצרָאֵי (בכל הס':וּמִצְרַיִם) אוֹלִיד יָת לוּדָאֵי וְיָת עֲנָמָאֵי וְיָת לְהָבָאֵי וְיָת נַפְתּוּחָאֵי:
@103 וְיָת פַּתְרוּסָאֵי וְיָת כַּסְלוּחָאֵי דִּי נְפָקוּ מִתַּמָּן פְּלִשְׁתָּאֵי וְיָת קַפּוּטְקָאֵי:
@104 וּכְנַעַן אוֹלִיד יָת צִידוֹן בָּכְרֵהּ וְיָת חֵת:
@105 וְיָת יְבוּסָאֵי וְיָת אֱמוֹרָאֵי וְיָת גִּרְגָּשָׁאֵי:
@106 וְיָת חִוָּאֵי וְיָת עַרְקָאֵי וְיָת אַנְתּוֹסָאֵי:
@107 וְיָת אַרְוָדָאֵי וְיָת צְמָרָאֵי וְיָת חֲמָתָאֵי וּבָתַר כֵּן אִתְבַּדָּרוּ זַרְעֲיַת כְּנַעֲנָאֵי:
@108 וַהֲוָה תְּחוּם כְּנַעֲנָאֵי מִצִידוֹן מָטֵי לִגְרָר עַד עַזָּה מָטֵי לִסְדוֹם וַעֲמוֹרָה וְאַדְמָה וּצְבוֹיִם עַד לָשַׁע:
@109 אִלֵּין בְּנֵי חָם לְזַרְעֲיָתְהוֹן לְלִישָׁנְהוֹן בְּאַרְעָתְהוֹן בְּעַמְמֵיהוֹן:
@110 וּלְשֵׁם אִתְיְלִיד אַף הוּא אֲבוּהוֹן דְּכָל בְּנֵי עֵבֶר אָחוּהִי דְּיֶפֶת רַבָּא:
@111 בְּנֵי שֵׁם עֵילָם וְאַשּׁוּר וְאַרְפַּכְשַׁד וְלוּד וַאֲרָם:
@112 וּבְנֵי אֲרָם עוּץ וְחוּל וְגֶתֶר וָמַשׁ:
@113 וְאַרְפַּכְשַׁד אוֹלִיד יָת שָׁלַח וְשֶׁלַח אוֹלִיד יָת עֵבֶר:
@114 וּלְעֵבֶר אִתְיְלִידוּ תְּרֵין בְּנִין שׁוּם חַד פֶּלֶג אֲרֵי בְּיוֹמוֹהִי אִתְפְּלִיגַת אַרְעָא וְשׁוּם אֲחוּהִי יָקְטָן:
@115 וְיָקְטָן אוֹלִיד יָת אַלְמוֹדָד וְיָת שָׁלֶף וְיָת חֲצַרְמָוֶת וְיָת יָרַח:
@116 וְיָת הֲדוֹרָם וְיָת אוּזָל וְיָת דִּקְלָה:
@117 וְיָת עוֹבָל וְיָת אֲבִימָאֵל וְיָת שְׁבָא:
@118 וְיָת אוֹפִר וְיָת חֲוִילָה וְיָת יוֹבָב כָּל אִלֵּין בְּנֵי יָקְטָן:
@119 וַהֲוָה מוֹתְבָנֵהוֹן מִמֵּשָׁא מָטֵי לִסְפַר טּוּר מָדִינְחָא:
@120 אִלֵּין בְּנֵי שֵׁם לְזַרְעֲיָתְהוֹן לְלִישָׁנְהוֹן לְאַרְעָתְהוֹן בְּעַמְמֵיהוֹן:
@121 אִלֵּין זַרְעֲיַת בְּנֵי נֹחַ לְתוּלְדָתְהוֹן בְּעַמְמֵיהוֹן וּמֵאִלֵּין אִתַּפְרָשׁוּ עַמְמַיָּא בְּאַרְעָא בָּתַר טוֹפָנָא:
@122 וַהֲוָה כָל אַרְעָא לִישָׁן חָד וּמַמְלָל חָד:
@123 וַהֲוָה בְּמִטַּלְהוֹן בְּקַדְמֵיתָא וְאַשְׁכָּחוּ בִקְעֲתָא בְּאַרְעָא דְבָבֶל וִיתִיבוּ תַמָּן:
@124 וַאֲמָרוּ גְּבַר לְחַבְרֵהּ הָבוּ נִרְמֵי לִבְנִין וְנוֹקְדִינוּן בְּנוּרָא יוֹקַדְתָּא (נ''י בְּנוּרָא) וַהֲוַת לְהוֹן לְבִנְתָּא לְאַבְנָא וְחֵימָרָא הֲוָה לְהוֹן לְשִׁיעַ:
@125 וַאֲמָרוּ הָבוּ נִבְנֵי לָנָא קַרְתָּא וּמַגְדְּלָא וְרֵישֵׁהּ מָטֵי עַד צֵית שְׁמַיָּא וְנַעְבֵּיד לָנָא שׁוּם דִּילְמָא נִתְבַּדַּר עַל אַפֵּי כָל אַרְעָא:
@126 וְאִתְגְּלֵי יְיָ לְאִתְפְּרָעָא עַל עוֹבָדֵי קַרְתָּא וּמַגְדְּלָא דִּי בְנוֹ בְּנֵי אֱנָשָׁא:
@127 וַאֲמַר יְיָ הָא עַמָּא חַד וְלִישָׁן חַד לְכֻלְּהוֹן וְדֵין דְּשָׁרִיוּ לְמֶעְבָּד וּכְעַן לָא יִתִּמְנַע מִנְּהוֹן כֹּל דִחַשִּׁיבוּ לְמֶעְבָּד:
@128 הָבוּ נִתְגְּלִי וּנְבַלְבֵּל תַּמָּן לִישָׁנְהוֹן דְּלָא יִשְׁמְעוּן (גְּבַר) אֱנַשׁ לִישָׁן חַבְרֵהּ:
@129 וּבַדַּר יְיָ יָתְהוֹן מִתַּמָּן עַל אַפֵּי כָל אַרְעָא וּמְנָעוּ לְמִבְנֵי (נ''י וְאִתְמְנָע מִלְּמִבְנֵי) קַרְתָּא:
@130 עַל כֵּן קְרָא שְׁמַהּ בָּבֶל אֲרֵי תַמָּן בַּלְבֵּל יְיָ לִישַׁן כָּל אַרְעָא וּמִתַּמָּן בַּדָּרִנּוּן יְיָ עַל אַפֵּי כָּל אַרְעָא:
@131 אִלֵּין תּוּלְדַת שֵׁם שֵׁם בַּר מְאָה שְׁנִין וְאוֹלִיד יָת אַרְפַּכְשָׁד תַּרְתֵּין שְׁנִין בָּתַר טּוֹפָנָא:
@132 וַחֲיָא שֵׁם בָּתַר דְּאוֹלִיד יָת אַרְפַּכְשָׁד חֲמֵשׁ מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@133 וְאַרְפַּכְשַׁד חֲיָא תְּלָתִין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת שָׁלַח:
@134 וַחֲיָא אַרְפַּכְשַׁד בָּתַר דְּאוֹלִיד יָת שֶׁלַח אַרְבַּע מְאָה וּתְלָת שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@135 וְשֶׁלַח חֲיָא תְּלָתִין שְׁנִין וְאוֹלִיד יָת עֵבֶר:
@136 וַחֲיָא שֶׁלַח בָּתַר דְּאוֹלִיד יָת עֵבֶר אַרְבַּע מְאָה וּתְלָת שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@137 וַחֲיָא עֵבֶר תְּלָתִין וְאַרְבַּע שְׁנִין וְאוֹלִיד יָת פָּלֶג:
@138 וַחֲיָא עֵבֶר בָּתַר דְּאוֹלִיד יָת פֶּלֶג אַרְבַּע מְאָה וּתְּלָתִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@139 וַחֲיָא פֶלֶג תְּלָתִין שְׁנִין וְאוֹלִיד יָת רְעוּ:
@140 וַחֲיָא פֶלֶג בָּתַר דְּאוֹלִיד יָת רְעוּ מָאתָן וּתְשַׁע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@141 וַחֲיָא רְעוּ תְּלָתִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד יָת שְׂרוּג:
@142 וַחֲיָא רְעוּ בָּתַר דְּאוֹלִיד יָת שְׂרוּג מָאתָן וּשְׁבַע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@143 וַחֲיָא שְׂרוּג תְּלָתִין שְׁנִין וְאוֹלִיד יָת נָחוֹר:
@144 וַחֲיָא שְׂרוּג בָּתַר דְּאוֹלִיד יָת נָחוֹר מָאתָן שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@145 וַחֲיָא נָחוֹר עֶשְׂרִין וּתְשַׁע שְׁנִין וְאוֹלִיד יָת תָּרַח:
@146 וַחֲיָא נָחוֹר בָּתַר דְּאוֹלִיד יָת תֶּרַח מְאָה וּתְשַׁע עֲשַׂר שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@147 וַחֲיָא תֶרַח שִׁבְעִין שְׁנִין וְאוֹלִיד יָת אַבְרָם יָת נָחוֹר וְיָת הָרָן:
@148 וְאִלֵּין תּוּלְדַת תֶּרַח תֶּרַח אוֹלִיד יָת אַבְרָם יָת נָחוֹר וְיָת הָרָן וְהָרָן אוֹלִיד יָת לוֹטּ:
@149 וּמִית הָרָן עַל אַפֵּי תֶּרַח אֲבוּהִי בְּאַרְעָא דְּיַלָּדוּתֵהּ בְּאוּרָא דְכַסְדָּאֵי:
@150 וּנְסִיב אַבְרָם וְנָחוֹר לְהוֹן נְשִׁין שׁוּם אִתַּת אַבְרָם שָׂרָי וְשׁוּם אִתַּת נָחוֹר מִלְכָּה בַּת הָרָן אֲבוּהָא דְּמִלְכָּה וַאֲבוּהָא דְּיִסְכָּה:
@151 וַהֲוַת שָׂרַי עֲקָרָה לֵית לָהּ וְלָד:
@152 וּדְבַר תֶּרַח יָת אַבְרָם בְּרֵהּ וְיָת לוֹט בַּר הָרָן בַּר בְּרֵהּ וְיָת שָׂרַי כַּלָּתֵהּ אִתַּת אַבְרָם בְּרֵהּ וּנְפָקוּ עִמְּהוֹן מֵאוּרָא דְּכַסְדָּאֵי לְמֵיזַל לְאַרְעָא דִּכְנָעַן וַאֲתוֹ עַד חָרָן וִיתִיבוּ תַמָּן:
@153 וַהֲווֹ יוֹמֵי תֶרַח מָאָתן וַחֲמֵשׁ שְׁנִין וּמִית תֶּרַח בְּחָרָן: פפפ:

@1 **אלה תולדת נח נח איש צדיק.** הואיל והזכירו ספר בשבחו, שנאמר (משלי י ז) זכר צדיק לברכה. דבר אחר ללמדך, שעיקר תולדותיהם של צדיקים מעשים טובים: **בדרתיו.** יש מרבותינו דורשים אותו לשבח, כל שכן שאלו היה בדור צדיקים היה צדיק יותר, ויש שדורשים אותו לגנאי, לפי דורו היה צדיק, ואלו היה בדורו של אברהם לא היה נחשב לכלום: **את האלהים התהלך נח.** ובאברהם הוא אומר (יז א) התהלך לפני, (כד מ) אשר התהלכתי לפניו, נח היה צריך סעד לתמכו, אבל אברהם היה מתחזק ומהלך בצדקו מאליו: **התהלך.** לשון עבר, וזהו שמושו של למד בלשון כבד, משמשת להבא ולשעבר בלשון אחד, (שם יג יז) קום התהלך, להבא, התהלך נח, לשעבר, (ש''א יב יט) התפלל בעד עבדיך להבא, (מלכים א ח מב) ובא והתפלל אל הבית הזה, לשון עבר, אלא שהוי''ו שבראשו הופכו להבא:
@3 **ותשחת.** לשון ערוה ועבודה זרה, כמו (דברים ד טז) פן תשחתון, כי השחית כל בשר וגו' : **ותמלא הארץ חמס.** גזל:
@4 **כי השחית כל בשר.** אפילו בהמה חיה ועוף נזקקין לשאינן מינן:
@5 **קץ כל בשר.** כל מקום שאתה מוצא זנות ועבודה זרה, אנדרלמוסיא באה לעולם והורגת טובים ורעים: **כי מלאה הארץ חמס.** לא נחתם גזר דינם אלא על הגזל: **את הארץ.** כמו מן הארץ, ודומה לו (שמות ט כט) כצאתי את העיר, מן העיר, (מ''א טו כג) חלה את רגליו, מן רגליו. דבר אחר את הארץ עם הארץ, שאף שלשה טפחים של עומק המחרשה נמוחו ונטשטשו:
@6 **עשה לך תבת.** הרבה ריוח והצלה לפניו, ולמה הטריחו בבנין זה, כדי שיראוהו אנשי דור המבול עוסק בה מאה ועשרים שנה ושואלין אותו מה זאת לך, והוא אומר להם עתיד הקדוש ברוך הוא להביא מבול לעולם, אולי ישובו: **עצי גפר.** כך שמו. ולמה ממין זה על שם גפרית, שנגזר עליהם להמחות בו: **קנים.** מדורים מדורים לכל בהמה וחיה: **בכפר.** זפת בלשון ארמי. ומצינו בתלמוד כופרא. בתיבתו של משה, על ידי שהיו המים תשים, דיה בחומר מבפנים וזפת מבחוץ, ועוד כדי שלא יריח אותו צדיק ריח רע של זפת, אבל כאן מפני חזק המים זפתה מבית ומבחוץ:
@8 **צהר.** יש אומרים חלון, ויש אומרים אבן טובה המאירה להם: **ואל אמה תכלנה מלמעלה.** כסויה משפע ועולה עד שהוא קצר מלמעלה ועומד על אמה, כדי שיזובו המים למטה: **בצדה תשים.** שלא יפלו הגשמים בה: **תחתים שנים ושלשים.** שלש עליות זו על גב זו, עליונים לאדם, אמצעים למדור לבהמה תחתיים לזבל:
@9 **ואני הנני מביא.** הנני מוכן להסכים עם אותם שזרזוני ואמרו לפני כבר (תהלים ח ה) מה אנוש כי תזכרנו: **מבול.** שבלה את הכל, שבלבל את הכל, שהוביל את הכל מן הגבוה לנמוך, וזהו לשון אנקלוס שתרגם טופנא, שהציף את הכל והביאם לבבל שהיא עמוקה, לכך נקראת שנער שננערו שם כל מתי מבול:
@10 **והקמתי את בריתי.** ברית היה צריך על הפרות שלא ירקבו ויעפשו, ושלא יהרגוהו רשעים שבדור: **אתה ובניך ואשתך.** האנשים לבד והנשים לבד, מכאן שנאסרו בתשמיש המטה:
@11 **ומכל החי.** אפילו שדים: **שנים מכל.** מן הפחות שבהם לא פחתו משנים, אחד זכר ואחד נקבה:
@12 **מהעוף למינהו.** אותן שדבקו במיניהם ולא השחיתו דרכם, ומאליהם באו, וכל שהתיבה קולטתו הכניס בה:
@14 **ויעש נח.** זה בנין התבה:
@15 **כי אותך ראיתי צדיק.** ולא נאמר צדיק תמים. מכאן שאומרים מקצת שבחו של אדם בפניו וכלו שלא בפניו:
@16 **הטהורה.** העתידה להיות טהורה לישראל, למדנו שלמד נח תורה: **שבעה שבעה.** כדי שיקריב מהם קרבן בצאתו:
@17 **גם מעוף השמים** וגו' **.** בטהורים הכתוב מדבר. וילמד סתום מן המפורש:
@18 **כי לימים עוד שבעה.** אלו שבעת ימי אבלו של מתושלח הצדיק שחס הקדוש ברוך הוא על כבודו ועכב את הפרענות. צא וחשוב שנותיו של מתושלח ותמצא שהם כלים בשנת שש מאות שנה לחיי נח: **כי לימים עוד.** מהו עוד, זמן אחר זמן, זה נוסף על מאה ועשרים שנה: **ארבעים יום.** כנגד יצירת הולד שקלקלו להטריח ליוצרם לצור צורת ממזרים:
@19 **ויעש נח.** זה ביאתו לתבה:
@21 **נח ובניו.** האנשים לבד והנשים לבד, לפי שנאסרו בתשמיש המטה, מפני שהעולם היה שרוי בצער: **מפני מי המבול.** אף נח מקטני אמנה היה, מאמין ואינו מאמין שיבא המבול ולא נכנס לתבה עד שדחקוהו המים:
@23 **שנים שנים.** כלם השוו במנין זה, מן הפחות היו שנים: **באו אל נח.** מאליהן:
@25 **בחדש השני.** רבי אליעזר אומר זה מרחשון, רבי יהושע אומר זה איר: **נבקעו.** להוציא מימיהן: **תהום רבה.** מדה כנגד מדה, הם חטאו ברבה רעת האדם (בראש' ו ה) ולקו בתהום רבה:
@26 **ויהי הגשם על הארץ.** ולהלן הוא אומר (פסוק יז) ויהי המבול, אלא כשהורידן, הורידן ברחמים שאם יחזרו יהיו גשמי ברכה, וכשלא חזרו היו למבול: **ארבעים יום** וגו' **.** אין יום ראשון מן המנין לפי שאין לילו עמו, שהרי כתיב ביום הזה נבקעו כל מעינות, נמצאו ארבעים יום כלים בעשרים ושמונה בכסלו, לרבי אליעזר שהחדשים נמנין כסדרן אחד מלא ואחד חסר, הרי שנים עשר ממרחשון ועשרים ושמונה מכסלו:
@27 **בעצם היום הזה.** למדך הכתוב שהיו בני דורו אומרים אלו אנו רואים אותו נכנס לתבה אנו שוברין אותה והורגין אותו, אמר הקדוש ברוך הוא אני מכניסו לעיני כלם (בר''ר) ונראה דבר מי יקום:
@28 **צפור כל כנף.** דבוק הוא, צפור של כל מין כנף, לרבות חגבים (כנף לשון נוצה כמו (ויקרא א יז) ושסע אותו בכנפיו שאפלו נוצתה עולה, אף כאן צפור כל מין מראית נוצה) :
@30 **ויסגור ה' בעדו.** הגין עליו שלא ישברוה, הקיף התבה דבים ואריות והיו הורגים בהם. ופשוטו של מקרא סגר כנגדו מן המים וכן כל בעד שבמקרא לשון כנגד הוא (בראש' כ יח) בעד כל רחם, (מ''ב ד ד) בעדך ובעד בניך, (איוב ב ד) עור בעד עור, (תהלים ג ד) מגן בעדי, (ש''א יב יט) התפלל בעד עבדיך, כנגד עבדיך:
@31 **ותרם מעל הארץ.** משקעת היתה במים אחת עשרה אמה כספינה טעונה המשקעת מקצתה במים ומקראות שלפנינו יוכיחו:
@32 **ויגברו.** מאליהן:
@34 **חמש עשרה אמה מלמעלה.** למעלה של גובה כל ההרים לאחר שהשוו המים לראשי ההרים:
@36 **נשמת רוח חיים.** נשימה של רוח חיים: **אשר בחרבה.** ולא דגים שבים:
@37 **וימח.** לשון ויפעל הוא ואינו לשון ויפעל והוא מגזרת ויפן ויבן. כל תבה שסופה ה''א כגון בנה, מחה, קנה, כשהוא נותן וי''ו יו''ד בראשה נקוד בחירק תחת היו''ד: **אך נח.** לבד נח, זהו פשוטו. ומדרש אגדה היה גונח וכוהה דם מטורח הבהמות והחיות. ויש אומרים שאיחר מזונות לארי והכישו, ועליו נאמר (משלי יא לא) הן צדיק בארץ ישלם:
@39 **ויזכר אלהים.** זה השם מדת הדין הוא, ונהפכה למדת רחמים על ידי תפלת הצדיקים, ורשעתן של רשעים הופכת מדת רחמים למדת הדין, שנאמר (בראשית ו ה) וירא ה' כי רבה רעת האדם וגו' ויאמר ה' אמחה, והוא שם מדת רחמים: **ויזכור אלהים את נח** וגו' **.** מה זכר להם לבהמות, זכות שלא השחיתו דרכם קודם לכן ושלא שמשו בתבה: **ויעבר אלהים רוח.** רוח תנחומין והנחה עברה לפניו: **על הארץ.** על עסקי הארץ: **וישכו.** כמו (אסתר ב א) כשוך חמת המלך לשון הנחת חמה:
@40 **ויסכרו מעינות.** כשנפתחו כתיב (ז יא) כל מעינות, וכאן אין כתיב כל, לפי שנשתירו מהם אותן שיש בהם צורך לעולם, כגון חמי טבריא וכיוצא בהם: **ויכלא.** וימנע, כמו (תהלים מ יב) לא תכלא רחמיך, (בראשית כג ו) לא יכלה ממך:
@41 **מקצה חמשים ומאת יום.** התחילו לחסור, והוא אחד בסיון. כיצד בעשרים ושבעה בכסלו פסקו הגשמים הרי שלשה מכסלו ועשרים ותשעה מטבת הרי שלשים ושנים, ושבט ואדר וניסן ואייר מאה ושמונה עשר הרי מאה וחמשים:
@42 **בחדש השביעי.** סיון והוא שביעי לכסלו שבו פסקו הגשמים: **בשבעה עשר יום.** מכאן אתה למד שהיתה התבה משקעת במים אחת עשרה אמה, שהרי כתיב (פסוק ה) בעשירי באחד לחדש נראו ראשי ההרים, זה אב שהוא עשירי (למרחשון) לירידת גשמים והם היו גבוהים על ההרים חמש עשרה אמה וחסרו מיום אחד בסיון עד אחד באב חמש עשרה אמה לששים יום, הרי אמה לארבעה ימים, נמצא שבששה עשר בסיון לא חסרו אלא ארבע אמות, ונחה התבה ליום המחרת, למדת שהיתה משקעת אחת עשרה אמה במים שעל ראשי ההרים:
@43 **בעשירי** וכו' **נראו ראשי ההרים.** זה אב, שהוא עשירי למרחשון שהתחיל הגשם. ואם תאמר הוא אלול ועשירי לכסלו שפסק הגשם, כשם שאתה אומר בחדש השביעי סיון והוא שביעי להפסקה. אי אפשר לומר כן, על כרחך שביעי אי אתה מונה אלא להפסקה, שהרי לא כלו ארבעים יום של ירידת גשמים ומאה וחמשים של תגברת המים עד אחד בסיון, ואם אתה אומר שביעי לירידה אין זה סיון והעשירי אי אפשר למנות אלא לירידה, שאם אתה אומר להפסקה והוא אלול, אי אתה מוצא בראשון באחד לחדש חרבו המים מעל הארץ, שהרי מקץ ארבעים משנראו ראשי ההרים שלח את העורב, ועשרים ואחד יום הוחיל בשליחות היונה, הרי ששים יום משנראו ראשי ההרים עד שחרבו פני האדמה, ואם תאמר באלול נראו, נמצא שחרבו במרחשון, והוא קורא אותו ראשון ואין זה אלא תשרי, שהוא ראשון לבריאת עולם, ולרבי יהושע הוא ניסן:
@44 **מקץ ארבעים יום.** משנראו ראשי ההרים: **את חלון התבה אשר עשה.** לצהר, ולא זה פתח התבה העשוי לביאה ויציאה:
@45 **יצוא ושוב.** הולך ומקיף סביבות התבה ולא הלך בשליחותו שהיה חושדו על בת זוגו, כמו ששנינו באגדת חלק (סנהדרין קח:) : **עד יבשת המים.** פשוטו כמשמעו. אבל מדרש אגדה מוכן היה העורב לשליחות אחרת בעצירת גשמים בימי אליהו, שנאמר (מלכים א' יז ו) והערבים מביאים לו לחם ובשר:
@46 **וישלח את היונה.** לסוף שבעה ימים שהרי כתיב ויחל עוד שבעת ימים אחרים, מכלל זה אתה למד שאף בראשונה הוחיל שבעה ימים: **וישלח.** אין זה לשון שליחות אלא לשון שלוח, שלחה ללכת לדרכה, ובזו יראה אם קלו המים שאם תמצא מנוח לא תשוב אליו:
@48 **ויחל.** לשון המתנה, וכן (איוב כט כא) לי שמעו ויחלו, והרבה יש במקרא:
@49 **טרף בפיה.** אומר אני שזכר היה לכן קוראו פעמים לשון זכר ופעמים לשון נקבה, לפי שכל יונה שבמקרא לשון נקבה, כמו (שה''ש ה יב) כיונים על אפיקי מים רוחצות, (יחזקאל ז טז) כיוני הגאיות כלם המות וכמו (הושע ז יא) כיונה פותה: **טרף.** חטף, ומדרש אגדה לשון מזון, ודרשו בפיה, לשון מאמר, אמרה יהיו מזונותי מרורין כזית בידו של הקדוש ברוך הוא ולא מתוקין כדבש בידי בשר ודם:
@50 **וייחל.** הוא לשון ויחל, אלא שזה לשון ויפעל וזה לשון ויתפעל. ויחל וימתין, וייחל ויתמתן:
@51 **בראשון.** לרבי אליעזר הוא תשרי, ולרבי יהושע הוא ניסן: **חרבו.** נעשה כמין טיט, שקרמו פניה של מעלה:
@52 **בשבעה ועשרים.** וירידתן בחדש השני בשבעה עשר, אלו אחד עשר ימים שהחמה יתרה על הלבנה, שמשפט דור המבול שנה תמימה היה: **יבשה.** נעשה גריד כהלכתה:
@54 **אתה ואשתך** וגו' **.** איש ואשתו, כאן התיר להם תשמיש המטה:
@55 **היצא.** הוצא כתיב היצא קרי. היצא, אמור להם שיצאו. הוצא, אם אינם רוצים לצאת הוציאם אתה: **ושרצו בארץ.** ולא בתיבה, מגיד שאף הבהמה והעוף נאסרו בתשמיש:
@57 **למשפחתיהם.** קבלו עליהם על מנת לדבק במינן:
@58 **מכל הבהמה הטהורה.** אמר לא צוה לי הקדוש ברוך הוא להכניס מאלו שבעה שבעה אלא כדי להקריב קרבן מהם:
@59 **מנעריו.** מנעריו כתיב משננער לצאת ממעי אמו נתן בו יצר הרע: **לא אסף. ולא אסף.** כפל הדבר לשבועה, הוא שכתוב (ישעיהו נד ט) אשר נשבעתי מעבר מי נח, ולא מצינו בה שבועה אלא זו שכפל דבריו והיא שבועה, וכן דרשו חכמים במסכת שבועות (לו א) :
@60 **עוד כל ימי הארץ** וגו' **לא ישבתו.** שש עתים הללו שני חדשים לכל אחד ואחד, כמו ששנינו חצי תשרי ומרחשון וחצי כסלו זרע, חצי כסלו וטבת וחצי שבט קור וכו' : **קור.** קשה מחורף: **חורף.** עת זרע שעורים וקטניות החריפין להתבשל מהר. הוא חצי שבט ואדר וחצי ניסן: **קציר.** חצי ניסן ואייר וחצי סיון: **קיץ.** חצי סיון תמוז וחצי אב, הוא זמן לקיטת תאנים וזמן שמיבשים אותן בשדות, ושמו קיץ כמו (שמואל ב טז ב) והלחם והקיץ לאכול הנערים: **חום.** הוא סוף ימות החמה חצי אב ואלול וחצי תשרי, שהעולם חם ביותר, כמו ששנינו במסכת יומא (כט א) שלהי קייטא קשי מקייטא: **ויום ולילה לא ישבתו.** מכלל ששבתו כל ימות המבול, שלא שמשו המזלות ולא נכר בין יום ובין לילה: **לא ישבתו.** לא יפסקו כל אלה מלהתנהג כסדרן:
@62 **וחתכם.** ואימתכם כמו (איוב ו כא) תראו חתת. ואגדה לשון חיות שכל זמן שהתינוק בן יומו חי אין אתה צריך לשמרו מן העכברים, עוג מלך הבשן מת, צריך לשמרו מן העכברים, שנאמר ומוראכם וחתכם יהיה, אימתי יהיה מוראכם על החיות, כל זמן שאתם חיים:
@63 **לכם יהיה לאכלה.** שלא הרשיתי לאדם הראשון לאכול בשר אלא ירק עשב, ולכם כירק עשב שהפקרתי לאדם הראשון, נתתי לכם את כל:
@64 **בשר בנפשו.** אסר להם אבר מן החי, כלומר כל זמן שנפשו בו לא תאכלו הבשר: **בנפשו דמו.** בעוד נפשו בו: **בשר בנפשו לא תאכלו.** הרי אבר מן החי ואף בנפשו דמו לא תאכלו, הרי דם מן החי:
@65 **ואך את דמכם.** אף על פי שהתרתי לכם נטילת נשמה בבהמה, את דמכם אדרוש מהשופך דם עצמו: **לנפשותיכם.** אף החונק עצמו אף על פי שלא יצא ממנו דם: **מיד כל חיה.** לפי שחטאו דור המבול והפקרו למאכל חיות רעות לשלוט בהן, שנאמר (תהלים מט יג) נמשל כבהמות נדמו, לפיכך הצרך להזהיר עליהן את החיות: **ומיד האדם.** מיד ההורג במזיד ואין עדים אני אדרוש: **מיד איש אחיו.** מיד שהוא אוהב לו כאח והרגו שוגג, אני אדרוש, אם לא יגלה ויבקש על עונו למחל, שאף השוגג צריך כפרה, ואם אין עדים לחייבו גלות והוא אינו נכנע, הקדוש ברוך הוא דורש ממנו. כמו שדרשו רבותינו זכרונם לברכה והאלהים אנה לידו במסכת מכות (י ב) הקדוש ברוך הוא מזמנן לפנדק אחד וכו' :
@66 **באדם דמו ישפך.** אם יש עדים המיתוהו אתם, למה, כי בצלם אלהים וגו' : **עשה את האדם.** זה מקרא חסר, וצריך להיות עשה העושה את האדם, וכן הרבה במקרא:
@67 **ואתם פרו ורבו.** לפי פשוטו הראשונה לברכה, וכאן לצווי. ולפי מדרשו להקיש מי שאינו עוסק בפריה ורביה לשופך דמים:
@69 **ואני הנני.** מסכים אני עמך, שהיה נח דואג לעסוק בפריה ורביה עד שהבטיחו הקדוש ברוך הוא שלא לשחת את העולם עוד, וכן עשה. ובאחרונה אמר לו הנני מסכים לעשות קיום וחזוק ברית להבטחתי, ואתן לך אות:
@70 **חית הארץ אתכם.** הם המתהלכים עם הבריות: **מכל יוצאי התבה.** להביא שקצים ורמשים: **לכל חית הארץ.** להביא המזיקין שאינן בכלל החיה אשר אתכם, שאין הלוכן עם הבריות:
@71 **והקימותי.** אעשה קיום לבריתי, ומהו קיומו, את הקשת כמו שמסים והולך:
@72 **לדרת עולם.** נכתב חסר, שיש דורות שלא הצרכו לאות לפי שצדיקים גמורים היו, כמו דורו של חזקיהו מלך יהודה, ודורו של רבי שמעון בן יוחאי:
@74 **בענני ענן.** כשתעלה במחשבה לפני להביא חשך ואבדון לעולם:
@76 **בין אלהים ובין כל נפש חיה.** בין מדת הדין של מעלה וביניכם שהיה לו לכתוב ביני ובין כל נפש חיה. אלא זהו מדרשו כשתבא מדת הדין לקטרג עליכם (לחיב אתכם) אני רואה את האות ונזכר:
@77 **זאת אות הברית.** הראהו הקשת ואמר לו הרי האות שאמרתי:
@78 **וחם הוא אבי כנען.** למה הצרך לומר כאן, לפי שהפרשה עסוקה ובאה בשכרותו של נח שקלקל בה חם, ועל ידו נתקלל כנען, ועדיין לא כתב תולדות חם, ולא ידענו שכנען בנו, לפיכך הצרך לומר כאן וחם הוא אבי כנען:
@80 **ויחל.** עשה עצמו חלין, שהיה לו לעסוק תחלה בנטיעה אחרת: **איש האדמה.** אדוני האדמה, כמו (רות א ג) איש נעמי: **ויטע כרם.** כשנכנס לתבה הכניס עמו זמורות ויחורי תאנים:
@81 **ויתגל.** לשון ויתפעל: **אהלו.** אהלה כתיב רמז לעשרת שבטים שנקראו על שם שומרון שנקראת אהלה, שגלו על עסקי היין, שנאמר השתים במזרקי יין (עמוס ו ו) :
@82 **וירא חם אבי כנען.** יש מרבותינו אומרים כנען ראה והגיד לאביו לכך הזכר על הדבר ונתקלל: **וירא את ערות אביו.** יש אומרים סרסו ויש אומרים רבעו:
@83 **ויקח שם ויפת.** אין כתיב כאן ויקחו אלא ויקח, למד על שם שנתאמץ במצוה יותר מיפת, לכך זכו בניו לטלית של ציצית, ויפת זכה לקבורה לבניו, שנאמר (יחזקאל לט יא) אתן לגוג מקום שם קבר. וחם שבזה את אביו נאמר בזרעו (ישעיה כ ד) כן ינהג מלך אשור את שבי מצרים ואת גלות כוש נערים וזקנים ערום ויחף וחשופי שת וגו' : **ופניהם אחורנית.** למה נאמר פעם שניה, מלמד שכשקרבו אצלו והצרכו להפך עצמם לכסותו, הפכו פניהם אחורנית:
@84 **בנו הקטן.** הפסול והבזוי, כמו (ירמיה מט טו) הנה קטן נתתיך בגוים בזוי באדם:
@85 **ארור כנען.** אתה גרמת לי שלא אוליד בן רביעי אחר לשמשני, ארור בנך רביעי להיות משמש את זרעם של אלו הגדולים, שהטל עליהם טורח עבודתי מעתה. ומה ראה חם שסרסו, אמר להם לאחיו אדם הראשון שני בנים היו לו, והרג זה את זה בשביל ירשת העולם ואבינו יש לו שלשה בנים ועודנו מבקש בן רביעי:
@86 **ברוך ה' אלהי שם.** שעתיד לשמור הבטחתו לזרעו לתת להם את ארץ כנען: **ויהי כנען עבד למו.** למס עובד:
@87 **יפת אלהים ליפת.** מתורגם יפתי, ירחיב: **וישכון באהלי שם.** ישרה שכינתו בישראל. ומדרש חכמים אף על פי שיפת אלהים ליפת, שבנה כרש שהיה מבני יפת בית שני, לא שרתה בו שכינה. והיכן שרתה, במקדש ראשון שבנה שלמה שהיה מבני שם: **ויהי כנען עבד למו.** אף משיגלו בני שם, ימכרו להם עבדים מבני כנען:
@91 **ותירס.** זו פרס:
@97 **להיות גבר.** להמריד כל העולם על הקדוש ברוך הוא בעצת דור הפלגה:
@98 **גבר ציד.** צד דעתן של בריות בפיו ומטען למרוד במקום: **לפני ה'.** מתכון להקניטו על פניו: **על כן יאמר כנמרד.** על כל אדם מרשיע בעזות פנים, יודע רבונו ומתכון למרוד בו, יאמר זה כנמרוד גבור ציד:
@100 **מן הארץ** וגו' **.** כיון שראה אשור את בניו שומעין לנמרוד ומורדין במקום לבנות המגדל, יצא מתוכם:
@101 **העיר הגדולה.** היא נינוה שנאמר (יונה ג ג) ונינוה היתה עיר גדולה לאלהים:
@102 **להבים.** שפניהם דומים ללהב:
@103 **ואת פתרוסים ואת כסלוחים אשר יצאו משם פלשתים.** משניהם יצאו, שהיו פתרוסים וכסלוחים מחליפין משכב נשותיהם אלו לאלו, ויצאו מהם פלשתים:
@107 **ואחר נפצו.** מאלו נפוצו משפחות הרבה:
@108 **גבול הכנעני.** סוף ארצו. כל גבול שבמקרא לשון סוף וקצה: **באכה.** שם דבר. ולי נראה כאדם האומר לחברו גבול זה מגיע עד אשר תבא לגבול פלוני:
@109 **ללשונותם בארצותם.** אף על פי שנחלקו ללשונות וארצות, כלם בני חם הם:
@110 **אבי כל בני עבר.** הנהר היה שם: **אחי יפת הגדול.** איני יודע אם יפת הגדול אם שם, כשהוא אומר (להלן יא י) שם בן מאת שנה וגו' שנתים אחר המבול, הוי אומר יפת הגדול, שהרי בן חמש מאות שנה היה נח כשהתחיל להוליד, והמבול היה בשנת שש מאות שנה לנח, נמצא שהגדול בבניו היה בן מאה שנה, ושם לא הגיע למאה שנה עד שנתים אחר המבול: **אחי יפת.** ולא אחי חם, שאלו שניהם כבדו את אביהם, וזה בזהו:
@114 **נפלגה.** נתבלבלו הלשונות, ונפוצו מן הבקעה, ונתפלגו בכל העולם. למדנו שהיה עבר נביא שקרא שם בנו על שם העתיד. ושנינו בסדר עולם (פרק א) שבסוף ימיו נתפלגו, שאם תאמר בתחלת ימיו, הרי יקטן אחיו צעיר ממנו והוליד כמה משפחות קודם לכן, שנאמר (פסוק כו) ויקטן ילד וגו' ואחר כך ויהי כל הארץ וגו' . ואם תאמר באמצע ימיו, לא בא הכתוב לסתום אלא לפרש, הא למדת שבשנת מות פלג נתפלגו:
@115 **ויקטן.** שהיה ענו ומקטין עצמו, לכך זכה להעמיד כל המשפחות הללו: **חצרמות.** על שם מקומו, דברי אגדה:
@122 **שפה אחת.** לשון הקודש: **ודברים אחדים.** באו בעצה אחת ואמרו לא כל המנו שיבור לו את העליונים, נעלה לרקיע ונעשה עמו מלחמה. דבר אחר על יחידו של עולם. דבר אחר ודברים אחדים, אמרו אחת לאלף ושש מאות חמשים ושש שנים הרקיע מתמוטט כשם שעשה בימי המבול, בואו ונעשה לו סמוכות:
@123 **ויהי בנסעם מקדם.** שהיו יושבים שם, כדכתיב למעלה (י ל) ויהי מושבם וגו' הר הקדם, ונסעו משם לתור להם מקום להחזיק את כלם, ולא מצאו אלא שנער:
@124 **איש אל רעהו.** אמה לאמה, מצרים לכוש [וכוש לפוט] ופוט לכנען: **הבה.** הזמינו עצמכם. כל הבה לשון הזמנה הוא, שמכינים עצמן ומתחברים למלאכה, או לעצה, או למשא. הבה, הזמינו אפרייליי''ר בלע''ז : **לבנים.** שאין אבנים בבבל, שהיא בקעה: **ונשרפה לשרפה.** כך עושין הלבנים שקורין טיולי''ש בלע''ז , שורפים אותן בכבשן: **לחמר.** לטוח הקיר:
@125 **פן נפוץ.** שלא יביא עלינו שום מכה להפיצנו מכאן:
@126 **וירד ה' לראות.** לא הצרך לכך, אלא בא ללמד לדינים שלא ירשיעו הנדון עד שיראו ויבינו. במדרש רבי תנחומא (אות יח) : **בני האדם.** אלא בני מי, שמא בני חמורים וגמלים, אלא בני אדם הראשון שכפר את הטובה ואמר (ג יב) האשה אשר נתתה עמדי, אף אלו כפרו בטובה למרוד במי שהשפיעם טובה ומלטם מן המבול:
@127 **הן עם אחד ושפה אחת.** כל טובה זו יש עמהן, שעם אחד הם ושפה אחת לכלם, ודבר זה החלו לעשות: **החלם.** כמו אמרם, עשותם, התחילו הם לעשות: **לא יבצר מהם** וגו' **לעשות.** בתמיהה. יבצר לשון מניעה, כתרגומו, ודומה לו (תהלים עו יג) יבצר רוח נגידים:
@128 **הבה נרדה.** בבית דינו נמלך, מענותנותו היתרה: **הבה.** מדה כנגד מדה, הם אמרו הבה נבנה, והוא כנגדם מדד ואמר הבה נרדה: **ונבלה.** ונבלבל. נו''ן משמש בלשון רבים, וה''א אחרונה יתרה כה''א של נרדה: **לא ישמעו.** זה שואל לבנה וזה מביא טיט, וזה עומד עליו ופוצע את מוחו:
@129 **ויפץ ה' אותם משם.** בעולם הזה. מה שאמרו פן נפוץ, נתקים עליהם, הוא שאמר שלמה (משלי י כד) מגורת רשע היא תבואנו:
@130 **ומשם הפיצם.** למד שאין להם חלק לעולם הבא. וכי אי זו קשה, של דור המבול או של דור הפלגה, אלו לא פשטו יד בעקר, ואלו פשטו יד בעקר כביכול להלחם בו, ואלו נשטפו, ואלו לא נאבדו מן העולם. אלא שדור המבול היו גזלנים והיתה מריבה ביניהם לכך נאבדו, ואלו היו נוהגים אהבה ורעות ביניהם, שנאמר שפה אחת ודברים אחדים. למדת ששנאוי המחלוקת וגדול השלום:
@131 **שם בן מאת שנה.** כשהוליד את ארפכשד שנתים אחר המבול:
@149 **על פני תרח אביו.** בחיי אביו. ומדרש אגדה יש אומרים שעל ידי אביו מת, שקבל תרח על אברם בנו לפני נמרוד על שכתת את צלמיו והשליכו לכבשן האש, והרן יושב ואומר בלבו אם אברם נוצח, אני משלו, ואם נמרוד נוצח, אני משלו. וכשנצל אברם אמרו לו להרן משל מי אתה, אמר להם הרן משל אברם אני. השליכוהו לכבשן האש ונשרף, וזהו אור כשדים. ומנחם בן סרוק פרש אור בקעה, וכן (ישעיה כד טו) בארים כבדו ה', וכן (שם יא ח) מאורת צפעוני. כל חור ובקע עמוק קרוי אור:
@150 **יסכה.** זו שרה, על שם שסוכה ברוח הקודש, ושהכל סוכין ביפיה. ועוד יסכה לשון נסיכות, כמו שרה לשון שררה:
@152 **ויצאו אתם.** ויצאו תרח ואברם עם לוט ושרי:
@153 **וימת תרח בחרן.** לאחר שיצא אברם מחרן ובא לארץ כנען והיה שם יותר מששים שנה, שהרי כתוב (יב ד) ואברם בן חמש שנים ושבעים שנה בצאתו מחרן, (פסוק כו) ותרח בן שבעים שנה היה כשנלד אברם, הרי מאה ארבעים וחמש לתרח כשיצא אברם מחרן, עדיין נשארו משנותיו הרבה. ולמה הקדים הכתוב מיתתו של תרח ליציאתו של אברם, שלא יהא הדבר מפורסם לכל ויאמרו לא קים אברם את כבוד אביו שהניחו זקן והלך לו, לפיכך קראו הכתוב מת, שהרשעים אף בחייהם קרויים מתים, והצדיקים אף במיתתן קרויים חיים, שנאמר (שמואל ב' כג כ) ובניהו בן יהוידע בן איש חי: **בחרן.** הנו''ן הפוכה, לומר לך עד אברם היה חרון אף של מקום בעולם:
@154 **רני עקרה.** ירושלים אשר היתה כלא ילדה: **לא חלה.** ל' לידה הוא שהיולדת על ידי חיל וחבלי' יולדת: **מבני בעולה.** בת אדום:
@155 **יטו.** למרחוק: **מיתריך.** הם חבלים דקים התלוים בשולי אהלים וקושרי' ביתדות שקורין קביל"ס בלע"ז ותוקעין בארץ:
@156 **תפרוצי.** תגברו:
@157 **עלומיך.** נעוריך:
@159 **כי תמאס.** כשתמאס פעמים שכועס עליה מעט:
@161 **בשצף קצף.** מנחם פתר חרי אף ודונש אמר במעט קצף כמו ברגע קטן עזבתיך וכן ת"י: **ובחסד עולם.** שיתקיים עד עולם:
@162 **כי מי נח זאת לי.** שבועה בידי והולך ומפרש דברו כאשר נשבעתי מעבור מי נח וגו':
@163 **כי ההרים ימושו.** אף אם תכלה זכות אבות ואמהות חסדי מאתך לא ימוש:
@164 **סוערה.** שלבה סוער ברובי צרות: **מרביץ בפוך.** רוצף רצפתך מאבני נופך:
@165 **כדכד.** מין אבן טובה: **שמשותיך.** י"ת אמך ומנחם חברו עם ישמשוניה ויש פותרין ל' שמש חלונות שחמה זורחת בהן ועושין כנגדו מחיצה במיני זכוכית צבעים לנוי ומדרש תהלים פותר שמשותיך ושמש ומגן ( תהלים פד ) שיני החומה: **לאבני אקדח.** י"ת לאבני גמר גומרין תרגום גחלים פתר אקדח לשון קדחי אש והם מין אבנים טובות בוערות כלפידי' והוא קרבונקל"א לשון גחלת ויש פותרין ל' מקדח אבנים גדולות שכל חלל הפתח קדוח בתוכו והמזוזות והמפתן והסף כולן מתוך האבן הם: **לאבני חפץ.** לאבני צרוך:
@167 **רחקי מעושק.** כמו ( לעיל נב ) התנערי מעפר תרחקי מן העושקי' אותך ( רחקי מעושק תרחק מלעשוק בני אדם כדרך שעושים רשעים שאוספי' ממון מגזל אבל אתם לא תצרכו לגזול כי לא תיראו מדלות ועניות וממחתה כי לא תבא ולא תקר' אליך אברבנאל ) ( בצדקה שתעשה תהיה נכונה בגאולת עולם ותהיה רחוקה מעושק בני אדם כי לא תראי אפי' פחד ויראה לא יהיה לך מהם ותהיה רחוקה ממחתה שלא תקרב אליך, איל"ה שלוח' ):
@168 **הן גור יגור אפס מאותי.** הן ירא יירא ויגור מגזרת רעו' אותו שאין אני עמו הוא שעיר: **מי גר אתך.** מי אשר נאסף עליך למלחמה, או מי גר מי שנתגרה בך, ורבותינו פירשוהו בגרים לומ' שאין מקבלי' גרים לימות משיחנו ואף בפשוטו של מקרא יתכן מי שנעשו גרים אתך בעניותך עליך יפול בעשירותך כמו על פני כל אחיו נפל ( בראשית כה ):
@169 **הנה אנכי.** אשר בראתי חרש המתקן כלי ואני אשר בראתי משחית המחבלו כלו' אני הוא שגריתי בך את האוי' אני הוא שהתקנתי לו פורעניות: **ומוציא כלי למעשהו.** לצורך גומרו כל צורכו:
@170 **כל כלי יוצר.** כל כלי זיין אשר ילטשוהו ויחדדהו בשבילך להלחם בך: **יוצר.** ל' חרבות צורים ( יהושע ה ) אף תשיב צור חרבו ( תהלים פט ):
@171 **הוי כל צמא.** הוי זה ל' קריאה וזימון וקיבוץ הוא ויש הרבה במקרא ( זכריה ב ) הוי הוי ונוסו מארץ צפון: **לכו למים.** לתורה: **שברו.** ל' לשבור בר ( בראשית מב ) קנו: **יין וחלב.** לקח טוב מיין וחלב:
@172 **למה תשקלו כסף.** למה תגרמו לכם לשקול כסף לאויביכם בלא לחם:
@173 **חסדי דוד.** שאגמול לדוד חסדיו:
@174 **לאומים.** שר וגדול עליהם ומוכיח ומעיד דרכיהם על פניהם:
@175 **הן גוי לא תדע תקרא.** לשמושך אם אלי תשמעו לשם ה' הנקרא עליך:

@1 **תולדו'.** קורות כטעם מה ילד יום.
@1 **צדיק.** נאמר על שלמות המדות הגוי גם צדיק תהרוג. ונאמר עם זה על שלמות המושכלות וצדיק באמונתו יחיה. ומזה העניין השני נאמר כאן.
@1 **תמי'.** רוצה לומר שלם.
@1 **בדורותיו.** אמר זה לפי שכבר היה נח בדורות רבים לאורך ימיו ובכלם נמצא הולך בצדקו.
@3 **ותשחת הארץ.** ר"ל אנשי הארץ וכן וכל הארץ באו מצרימה.
@3 **לפני האלהים.** ר"ל שהשם ראה דרכיהם הרעים כדרך כי עיניו על דרכי איש. או יהיה הרצון בזה לפני הגדולים ומנהיגים שלא היו בושים מהם ואין מי שייסר אותם על רוע מעשיהם.
@3 **חמס.** הוא הגזל שזכר במה שקדם שהיו הגדולים חוטפים הנשים ובאים עליהם בחזקה ויתכן שכבר נטו מפני השקעתם בזאת התכונה הפחותה אל הגזל גם אל שאר הדברים.
@4 **כי השחית כל בשר.** ר"ל כל בני האדם כטעם יבאו כל בשר להשתחות לפני. ואמר שהשחיתו דרכם כי מרוב נטיתם לתאות המשגל השחיתו הדרך הנהוג והיו באים על הנשים שלא כדרכן ועל הזכר ועל הבהמה כמו שאמרו בב"ר.
@5 **מפניהם.** בסבתם כטעם מפני מי המבול והרצון בזה שאלו האנשים היו סבה שימצאו בהם אלו המדות הפחותות מצד בחירתם הרעה כי בבחירתם הוא להתנהג במנהגים המשובחים או בהפכם.
@5 **והנני משחיתם את הארץ.** ר"ל מן הארץ. כטעם כצאתי את העיר או יהיה הרצון באמרו את הארץ עם הארץ והטעם שהוא גזר להשחיתם השחתה תשחת בה הארץ הנגלית אשר יתהוו בה הצמחים והב"ח הארציים. ולזה הוצרך השם לקחת עצה להציל מיני הב"ח כי הם ימותו בלי ספק במי המבול.
@6 **גופר.** הוא עץ יתקיים זמן ארוך ולזה בחרו כי זאת התיבה היה צריכה שתהיה באופן שישלם בה הקיום זמן ארוך והוא מין אחד ממיני הארזים כמו שביארו רבותי' ז"ל ולא הוצרכה להיותה מעץ קל על פני המים כי האויר אשר בה ימנעוה מהצלילה במים.
@6 **קנים.** הם חדרים קטנים ומקומות קטנים לשום בהם מין מין מהעופות ושאר הב"ח. וכבר תמצא לשון קן בזולת העוף כאמרו עם קני אגוע ואם בין כוכבים שים קנך.
@6 **בכופר.** הוא דבר מתמרח כמו הזפת והדומה לו ימנע מהכנס המים כדבר והוא עם זה מתקיים מאד ואולי הוא טיט אד יעשוהו בקיאי הצורפים אשר הוא מתמרח ומתקיים קיום נפלא.
@6 **וכפרת.** הרצון בו שימרח בו הכופר ואולי צוה למרוח בו הכופר מבית ומבחוץ לתוספת שמירה כדי שלא יכנסו המים בתיבה.
@8 **צהר.** הוא מעניין צהרים והרצון בו שיעשה בו מקום יגיע ממנו האור וידמה לי שבחלון ההוא הושם גשם ספיריי יעבור בו האור ושהחלון שבז' התואר ייוחד בלשוננו בשם צהר לפי שכבר נשאר המקום ההוא סתום ולא ישתמש מהחלון ההוא כי אם לאורה.
@9 **המבול.** הוא מעניין בלילה ועירוב כי מדרך המים שיעשו זה.
@17 **גם מעוף השמים שבעה שבעה.** ר"ל מהטהורים כי כבר קדם המאמר שיביא מהעוף שנים מכל מין ועתה ביאר שמהמינים הטהורים מהעוף יביא שבעה זכר ונקבה וקצר המאמר בעוף להשענו על מה שאמר בבהמה שיכניס מן הטהורה ארבע עשר מכל מין ומהטמאה שנים.
@18 **היקום.** הוא שם כולל לכל חי אשר על פני האדמה.
@25 **נבקעו כל מעיינות תהום.** הרצון בזה שכל המעיינות אשר להם תהום רבה נכרו מימיהם מאד מצד רבוי הויית מימיהם אז בבטן הארץ.
@25 **וארובות השמים נפתחו.** הוא משל לרבוי המים אשר נתהוו אז במקום הווית המטר עד שירדו בשפע כאלו נפתחו להם ארובות והנה הסכימו שתי אלו הסבות יחד ר"ל התהוות רבוי המים בעומק הארץ והתהוות רבוי המים בחלק האמצעי מן האויר אשר יתהוה בו המטר עד שגברו המים בזה האופן שזכר.
@30 **ויסגור יי' בעדו.** ר"ל שה' יתע' הגין עליו שלא הזיקוהו החיות רעות אשר שם אותם בתיבה.
@39 **וישוכו.** וינוחו. ר"ל שלא גברו.
@40 **ויכלא.** וימנע.
@48 **ויחל.** מעניין תוחלת וכן וייחל.
@49 **טרף בפיה.** הנה תאר היונה בשם זכר ונקבה יחד כמו רוח גדולה וחזק ועניינו שזה הב"ח והוא היונה טרף בפיה עלה זית או תהיה הבי"ת נוספת כמו שזכר החכם א"ע והרצון בו שפיה טרף עלי זית.
@51 **חרבו.** הוא מעניין יובש.
@59 **וירח יי' את ריח הניחוח.** הוא עד"מ לדבר בלשון בני אדם כי לא יתפעל השם ית' בהפעלות החושי'.
@59 **ויאמר יי' אל לבו.** הרצון בו שלא גלה הש' ית' זה הסוד לנביא כמו שידבר האדם אל לבו ולא ישמע אחר דבריו וזה העניין היה שהוא גזר שלא ישחית עוד הארץ בעבור האד' כמו שעשה בעניין המבול ולא יוסיף ג"כ להכות כל חי או ירצה בזה שלא יקלל עוד את האדמה בעון האד' כמו שעשה שקלל אותה בעון קין והביאור הראשון נאות יותר.
@62 **וחתכם.** הוא מעניין חתת.
@64 **אך בשר בנפשו דמו.** אמרו ז"ל בב"ר שזה אזהרה לבני נח שלא יאכלו אבר מן החי וירצח בו לפי זה הפירוש שלא יאכלו הבשר אשר בנפשו דם הבשר ההוא ר"ל שלא יאכלו בשר הלקוח מהב"ח בדרך שישאר כח בנפש הב"ח ההוא להוות הדם אשר היה ראוי שיובילוהו אל החלק ההוא מהבשר. ולזה ראוי שלא יקחו בשר לאכול מב"ח בדרך שישאר הב"ח ההוא חי. וזה הפירוש נפלא מאד בלשון זה הצווי.
@65 **אך את דמכם לנפשותיכם אדרוש.** ר"ל אם תהרגו קצתם קצת.
@65 **מיד כל חיה אדרשנו.** פירשו בו המפרשים שהשם ידרוש מהחיה אם תהרג האדם וזה בלתי נכון. כי הב"ח אינם בעלי שכל שיהיה ראוי שיענשו על הרע כשיעשוהו וקצת האחרונים פירשו שהשם ידרוש מיד האדם אם יהרוג רעהו באמצעות החיה כאלו תאמר אם כפתו לפני ארי וטרפו הארי והוא יותר נאות אלא שלא ישלם בו ביאור הנמשך מהפסוק ושאין לשון הפסוק נאות לזאת הכוונה. והנראה לי כי המ"ם תשמש בכאן שימוש הפועל לא שימוש המקבל כי המ"ם תשמש שני אלו השמושים בלשונות וזה שכבר יאמר שמהכסף נעשה הטבעת. והנה הכסף ההוא המקבל לצורת הטבעת ואמר שמהאומן יגיע שלימות המלאכה והנה האומן הוא הפועל המלאכה וכזה תמצא שאמרו ואת דמו מידך אבקש. היה שמושה מ"ם בו שימוש המקבל כי הוא יקבל העונש על זה כשלא הזהיר הרשע ואמרו מי בקש זאת מידכם רמוס חצרי היה שימוש המ"ם בו שימוש הפועל כי הם פועלים הרמיסה. ומזה העניין השני נמצאו רבים בדברי הנביאים וממנו יהיה אמרו מיד כל חיה אדרשנו. והרצון בזה כשיהרגו האנשים קצם קצת יקח הש' ית' נקמתו מההורג וידרוש דם ההרוג' מיד כל חיה. ר"ל שהוא יסבב שהחיו' ימיתוהו כדרך מה שאמרו רז"ל אע"פ שארבע מיתות בטלו דין ארבע מיתות לא בטלו.
@78 **וחם הוא אבי כנען.** ר"ל שהיו מתדמים ברוע והנה הגיע מרוע תכונת חם שראה ערות אביו ולא כסה אותה גם לא עצם עיניו מראות.
@84 **בנו הקטן.** כנוי בנו שב אל חם כי כנען היה בנו הקטן והנה חם לא היה הבן הקטן לנח אבל שם היה הקטן ולזה הקדים אחר זה תולדות יפת ואח"כ תולדות חם ואחר כך תולדו' שם. ולזה אין ראוי שיהיה שב אמרו בנו הקטן אל חם.
@85 **עבד עבדים.** רוצה לומר עבדות חזק ונפלא כמו העניין בקדש הקדשים שהרצון בו שהיו במדרגה גבוהה מהקדושה.
@87 **יפת.** רוצה לומר ירחיב.
@97 **להיות גבור בארץ.** ר"ל שהוא החל לרדוף אחר השררה והנצוח לחשבו שהטוב יהיה הכבוד והנצוח והרע הפכו.
@98 **הוא היה גבור ציד לפני יי'.** ר"ל שהוא היה גבור לצוד האנשים ולהכניעם תחתיו עד שכבר מלך במקומות רבים והוציא משם אשור שהיה מבני שם ולא נשמר מעשות חמס בפרהסיא לפני הש' ית'. ר"ל שהש' ית' רואה כל מעשיו כטעם ותשחת הארץ לפני האלהים. והנה בני נח הוזהרו על הגזל כמו שקדם.
@98 **על כן יאמר.** ר"ל שבעת נתינת התורה היה זה המאמר מפורסם שיאמרו אותו על האיש האכזרי הרודף אחר השררה והנצוח.
@101 **היא העיר הגדולה.** שב אל רסן לפי מה שאחשוב כי הוא יותר ראוי לפי מנהג הלשון. ואעפ"י שכבר מצאנו בנינוה שהיא עיר גדולה בימי יונה הנה זה לא יחייב שיהיה שב אל נינוה.
@102 **לודים ענמים.** ושאר השמות הנמשכים להם הם כלם שמות משפחות נקראות בשם המקומות אשר ישבו בהן הלא תראה שהכפתורים נקראים על שם כפתור שהיה מקומם. וכן פלשתי' נקראים על שם פלשת. וזכר שמהכסלוחים נשתלשלו שתי משפחות אחרות וזולתם והם פלשתים וכפתורים.
@110 **אבי כל בני עבר.** הם ישראל כי הם נקראו עברים אמר יי' אלהי העברים ויחסו להם לפי שהם היותר נכבדים מזרעו.
@110 **אחי יפת הגדול.** ידוע שיפת היה הגדול לפי שנח היה בן ת"ק שנה כשהוליד ולזה היה לגדול ק"כ שנה שנתים אחר המבול והנה מצאנו שהיה שם בן מאה שנה שנתים אחר המבול ועוד שהתורה הקדימה לספר תולדות יפת קודם תולדות שם והנה יחס שם אל יפת שהוא הגדול להיותם יחד טובים כמו שקדם. וחם לא יחסו שיהיה אחיהם.
@125 **וראשו בשמים.** רוצה לומ' שיהיה גבוה מאד על דרך ערים גדולות ובצורות בשמים.
@125 **ונעשה לנו שם.** ר"ל שיהיה המגדל סבה שיעשו להם שם וזכר שכולם הם בני איש אחד והוא הוליד אותם באופן אשר השתלשלו ממנו ובזה ישאר זכרונם תמיד כי יתיחסו כלם לראשוני' וזה שהמגדל ישאיר זכרם כל זמן קייומו כי הוא יקרא על שם בוניו. וזה ג"כ יהיה סבה אל שישכנו שם ובמקומות הקרובים לראותם המגדל ההוא למרחוק פן יפוצו על פני כל הארץ לבקש מקומות לעבודת האדמה ויתפרדו איש מעל אחיו והנה היו אומרים זה לחשבם כי יותר טוב היה להם הקבוץ מהפירוד.
@126 **וירד יי'.** הוא על דרך משל לדבר כלשון בני אד' כי ה' יתע' יודע הכל כמו שהתבאר בשלישי מספר מלחמות יי'.
@128 **הבה נרדה.** הוא משל לירידת גזירתו בהם.
@128 **ונבלה.** ונבלבל.

@1 **ביאור דברי הפרשה:**
@1 **אלו** המקרים שקרו לנח ועניניו והנה היה נח ישר במדותיו ובעיונו ושלם בכל אחת מהדורות אשר היה בהם לא נמצא בו רק טוב אך הלך תמיד בדרכי ה' יתע' וכבר הוליד נח ג' בנים כמו שנזכר במה שקדם. והם שם וחם ויפת. ויפת הוא הגדול כמו שיתבאר במה שנזכר במה שיבא ואולם הקדים שם למעלתו ומפני שהתחיל מהקטן השלים בגדול והקדים מפני זה חם ליפת והנה קודם זה הזמן שחתו דרכם אנשי הארץ לעיני הש"י ומלאה הארץ עושק וחמס כי לרוב המשכם אחר תאו' המשגל היו חוטפי' הנשים כמו שקדם ומפני זה אולי נסתבכו ג"כ בזאת המדה הפחותה עד שהיו חוטפים קצתם מקצת כסף ושוה כסף וכאשר ראה השם שהארץ נשחתה כי השחית כל בשר איש מהאנשים את דרכו ונמשך לפועל המשגל בזנות ובדרכים מגונים לא ישלם בהם פרי ושהם בכל יום מוסיפים לחטוא עד שימשך מזה הפסד במה שכוון במין האנושי מהשלמות אמר הש"י לנח שכבר בא קץ הדור ההוא שיכלה לפי מה שהוא רואה ממעשיהם המקולקלים כי הם בעצמם היו סבה אל רוע מעשיהם מפני בחירתם הרעה ולזה גזר עליהם שישחתו וישחת עמהם מקום הנגלה מהארץ אשר היה מציאותו בעבור הדם ושאר הב"ח הארציי' וזה אמנם יהיה כשיביא עליהם מבול מים שישטוף הארץ בכללה ולפי שנח נמצא צדיק לפני השם יתע' ולא למד מאנשי דורו השגיח השם בו להצילו וצוה אותו מפני זה שיעשה תיבה גדולה. מעצי גופר שיהיו חזקי הקיום והיו עם זה ארוכים מאד ושיעשה שם חדרים רבים קטנים גדולים להשיב בחדר חדר מה שהביא אליו אל התיבה מכל מין ומין מהב"ח הארציים ושיכפר אותה מבית ובחוץ בכופר לתוספת שמירה שלא יכנסו שם המים. וצוהו שיעשה אותה בשיעור יאות להחזיק מה שהוכרח להכניס בה ממיני הב"ח הארציי' ומה שיצטרך להם מהמזון לשנה אחת שמשית שיהיה זמן המבול ושישאר שם עם זה מקום יכניס בו הזבל בזמן היותם בתיבה וזה השיעור הספיק לפי מה שנגלה לנח בנבואה כשיהיה אורך התיבה שלש מאות אמה באמות הנהוגות שהאמה מהם היא בת ו' טפחים ורחבה חמשים אמה וקומתה ל' אמה והנה היה רחבה יותר מקומתה ולזה לא יתכן בה שתהפך ולזאת הסב' צוהו הש' ית' שיעשה התיבה בזה השיעור ושיעשה מקום סתום בגשם ספריי יכנס ממנו האור בתיבה כי האור הוא הכרחיי מאד לכל ב"ח. וצוהו שלא יהיה כסוי התיבה מלמעלה ישר השטח אבל יהיה משופע מכל הצדדים הארבעה באופן שלא יהיה למעלה משטח ישר כי אם אמר אחת באורך ולזה יהיה רוחב השטח ההוא אשר מלמעלה ששית אמה ביחס הרוחב אל האורך כי היה רוחב התיבה ששית ארכה והנה כסוי התיבה הוא ממדרגת מחודד שנקטם מפאת ראשו מעט וזה ממה שהוסיף שמירה בתירה שלא תתהפך. וצוהו שישים פתח התיבה אשר ממנו יכנס בה מה שיכנס בצד התיבה לא עליה לשמירה שלא יכנס מים בתיבה. וצוהו שיעשה בה מדורים רבים תחתיים שניים ושלישיים למה שיצטרך בה שיהיו בה מקומות להכיל הדברים המתחלפי' אשר הוכרחו להיות שם כדי שתשלם ההצלה למיני הב"ח בכללם. ואמנם צוהו בעשיית זאת התיבה מפני שהוא גזר להביא מבול מים על הארץ ישחתו כל הב"ח הארציים ואמר אליו שהוא יקיי' את בריתו אתו להצילו להשגחתו בו וזה אמנם יהיה בשיכנסו בתיבה אשר צוהו לעשותה הוא ובניו ואשתו ונשי בניו ואמנם הקדים הוא ובניו לנשיהם להיות האנשי' הם העקר בבריאה והנשים אמנם היו לעבודתם ולקיום המין. גם אפשר שהעירם בזה שלא ישמשו בתיבה כי עת רעה הוא ולזה ראוי שיכנע לבכם לעבוד ה' ית' כפי מה שאפשר להם כדי שתדבק השגחתו בהם כל ימי היותם בתיבה ולזה צוה שיעמדו האנשים לבד והנשים לבד וזה הברית אשר זכר הוא לפי מה שאחשוב שעשהו הש' ית' ביום הזה לקיים העולם בדרך שלא יצטרך עוד אל כמו זה האופן מהבריאה אשר ברא בששת ימי בראשית כמו שביארנו בפרשת ויכלו וזה הברית אמנם הקימו עם נח במה שצוהו מעשיית התיבה בתאר הנזכר ושיכנס בתיבה הוא ובניו ונשיהם ושיכניס עמו מכל מין ומין מהב"ח ההולך והמעופפים זכר ונקבה לכל הפחות כדי שיתקיימו כל מיני הב"ח ואולי כדת הש' ית' ברית עם נח קודם זה ואם לא נזכר והביאור הראשון נאות יותר לפי מה שאחשוב והנה צוהו השם שיכניס מהם י"ד הם אשר היו טהורים לפי משפטי התורה ואמנם הוסיף באלו המיני' להיותם יותר הכרחיים למין האנושי וזה מעניינם מבואר והנה זאת הנבואה היתה ק"כ שנה קודם בא המבול כמו שזכרנו בסוף פרשת בראשית. ולזה היה פנאי רב לנח לעשות זאת התיבה ולבקש אלו המינים מהב"ח עם שכבר נעזר בזה הפועל מהש' ית' והנה צוהו הש' יתע' שיקח מכל המזונות הנאותי' למין מין מהב"ח כדי שיהיה לו ולהם לאכלה בהיותם בתיבה ולזה חוייב שידע נח הזמן שיעמדו בתיבה כדי שיוכל לשער מה שיספיק להם מהמזון. וחוייב מזה ג"כ שידע נח המזונות הנאותים למין מין והשיעור הנאות שיקח הב"ח ההוא מהמזון ההוא וזאת המלאכה אשר המציאה יובל וכן ראוי שתדע שנח היה יודע כל שאר המלאכות אשר המציאום זרע קין כמו שקדם או אחד מבניו ולולי זה כבר אבדו המלאכות ההם בבא המבול ולא יצדק בממציאי המלאכות ההם מה שאמר בתורה שהמלאכות האלו השתלשלו מהם כאמרו אבי כל תופש כינור ועוגב אבי יושב אהל לומקנה. וכן ההיקש באומנו' הנחשת והברזל ואם לא זכר בו בביאור שתהיה זאת המלאכה משתלשלת ממנו כמו שזכרנו במה שקדם. והנה כבר מצאנו בביאור שנח ג"כ היה בקי בעבודת האדמה אמר ויחל נח איש אדמה. וראוי שתדע שהב"ח שימצא מזונם לפי הנהוג מה שלא יאות שינתן להם בתיבה כמו העשב והתבן והבשר נתן להם מהמזונות הנאותים להם מהזרעים כמו ממיני התבואה והקטנית ושאר הזרעים והפירות אשר יתכן בהם שיהיו מזונות לב"ח ההם. ובזה האופן היה אפשר שתכיל התיבה כל אישי מיני הב"ח הנכנסים בו מזונותיהם לשנה אחת והזבל אשר יעשו אלו הב"ח בשנה אחת. וראוי שתדע שמיני הצמחים אשר יתכן הפסדם מפני המבול השגיח הש' ג"כ בהם בזה האופן כי כבר חוייב שישים נח מהזרעי' ההם בתיבה בדרך שישאר מהם לזרוע אחר המבול ולא זכרה זה התורה בביאור לפי שהרבה מהצמחים לא נצטרכו אל זה והם כמו האילנות ולזה השמיטה התורה זכרו עם שזה דרך התורה לזכור קצת הפרטים ולעזוב קצת. והנה זכרה הב"ח להיותם יותר נכבדים מהצמחים והיותר נכון שנאמר שזה נכלל בתורה במה שאמרה והיה לך ולהם לאכלה. ר"ל כי יחוייב מזה שיספיקו הזרעים ההם להיות מהם מזונות הב"ח בתיבה ואחר צאתם ממנה וזה יהיה כשיזרעו בארץ כי אי זה תועלת יהיה כשיהיה להם מזון בתיבה ואחר שיצאו מן התיבה לא יהיה להם מזון וימותו הם זה המאמר מבואר הבטול כי הצלתם שם תהיה אם כן לבטלה ולא יתקיים מה שרצהו השם יתע' להחיות זרע על פני כל הארץ ולזה הוא מבואר שכבר יוחייב מזה שישאר מכל הזרעים לזרוע בארץ אחר צאתם מהתיבה וספרה התורה שנח עשה התיבה והשתדל לעשות כל מה שצוהו השם יתע' מהכנת מיני הב"ח ומזונותיהם. והנה ז' ימים קודם המבול צוהו השם יתע' להכנס בתיבה הוא וביתו ולא זולתם עמם לפי שנח לבדו נמצא צדיק בדור ההוא ושאר האנשים היו כלם מחוייבים כליה לרוע מעשיהם וזה לאות שאם היה שם צדיק זולתו היה נצול עמו וצוהו שיכניס עמו מאישי מיני הב"ח המספר שנזכר במה שקדם ואולי עשה זה כי כשיראו זה הדור הרע ההוא אולי יכנע לבבם וישובו לש' יתע' וירחמם כי לא חפץ ה' במות הרשע כי אם בשובו מדרכיו וחיה. והם לא נכנעו אבל החזיקו בדרכם הרעה וספר אחר זה שעש נח כל אשר צוהו ה' יתע' ושנח היה בן שש מאות שנה כשבא המבול ושכבר בא נח אל התיבה עם שאר הב"ח כאשר צוהו השם יתע' מפני מי המבול העתידים לבא לימים עוד שבעה וכשהגיעו ז' הימים התחילו לרדת מי המבול וזה היה בשנת שש מאות שנה לחיי נח בחדש השני והוא אייר לפי הנראה לי כי ניסן הוא ראש לחדשים כמו שנזכר בתורה עם שהזמן הזה היה יותר נכון להיות בו זה המופת יותר ממרחשון כי תקופת ניסן לחה ותקופת תשרי יבשה והשם יתעלה עושה תמיד המופתים בסבה היותר נאותות כמו שזכרנו במה שקדם. והנה ידעת שכבר נחלקו בזה הענין רבי אליעזר ור' יהושע וספר שאז נתהוו המים הויה נפלאה בבטן הארץ ובחלק האמצעי מהאויר עד שנתכסו כל ההרים הגבוהים אשר תחת כל השמי', וספר שבעצומו של יום ביום אשר צוה השם לנח שיכנס בתיבה ויכניס עמו ממיני הב"ח מה שצוהו הש' ית' השלים נח דבר ה' כדי שיראו זה כל האנשים אשר בדור ההוא וישובו אל ה' וירחם אותם. וזכר שכבר הגין הש"י עליו והשגיח בו בדרך שלא קרהו נזק בהיותו בתיבה לא ממי המבול ולא מהחיות אשר הכניס עמו בתיבה ולא מהאנשים אשר היו מחוץ והנה השלים זה הספור והפליג להאריך בו לרב התועלת המגיע ממנו. ולזה דקדק מספר הימים אשר ירד הגשם בלי הפסק ובשאר הפרטים לישב יותר בלבנו אמתת זה הספור כי הרבה סברה שנאמין יותר בספורים כשיסופר מענינים פרטים רבים וספר שבשנת שש מאות שנה ואחת לחיי נח בכ"ז יום לחדש השני יבשה הארץ. הנה אם כן היה מהתחלת המבול עד יבשת הארץ שנה שמשית שהוא י"ב חדש מחדשי הלבנה וקרוב מי"א יום כמו שנזכר בב"ר. וכאשר יבשה הארץ צוה הש' ית' לנח שיצא מהתיבה הוא ובניו ונשיהם וכל מיני הב"ח אשר עמם ויפרו וירבו על הארץ ולא יצטרכו עוד לפרות ולרבות בתיבה. אמרו בב"ר על הארץ ולא בתיבה ומהנראה שב"ח שמשו בתיב' כי זה הוא טבעי להם ואינם בעלי שכל שישלים להם צווי שלא ישמשו בתיבה ולזה ידמה שאמ' שהם יצאו למשפחותיהם ר"ל לפי שהם לא נתחברו בתיבה עם שולת מינם. ולזה הולידו תולדות ממינם ועשה נח כל אשר צוה הש' יתע' לא הפיל דבר והנה כל מה שעשה עשה בדבר הש' ית' גם לא התעורר לצאת מהתיבה אף על פי שכבר ראה שיבשה הארץ עד שצוהו הש' ית'. שיצא ואחר כן בנה נח מזבח לכבוד השם להורות כי הוא לבדו ראוי שיעבד לא ע"ז כמו שעשו הדורות הקודמים ולזה העלה עולות במזבח מהבהמה הטהורה ומהעוף הטהור כי הם המינים היותר נבחרים כמו שיתבאר במקומו בג"ה. או עשה זה כדי שתגיעהו הנבואה כמו שנבאר אח' השלימנו דברי הספור הזה וספר שכבר קבל ה' קרבנו ושעה אליו ואמר שלא יוסיף עוד להשחית האדמה בעון האדם לפי שיצר לב האדם רע מנעוריו ויטה האדם מפני זה אל התאוות הגופיות והנה יקשה צאתו מזאת התכונה הרעה לא יקבל המוסר בזה מזולתו וזה היה סבה לדורות הקודמים אשר נשחתו במימי המבול לנטות אל מה שנטו עליו מהתאוות כי עדין לא נתפשטה בדורות ההם ידיעת האמת בה. ואיך ראוי שיתנהגו בענין הטובות והרעות ואולם עתה שלא נשאר רק נח וביתו וכבר השיג נח האמת בזה הנה יקבלו המוסר ממנו הבאים אחריו מזרעו ולזה לא יתכן שימצא לעולם המין האנושי בכמו זה האופן מרוע ההנהגה אשר היה בו הדור הנשחת במי המבול. ובהיות העניין כן הנה לא יצטרך הש' יתע' אל כמו זה האופן מהגעת העונש לאנשים במה שיבא. ולזה גזר הש' ית' שלא יוסיף עוד להכות את כל חי כאשר עשה במי המבול ושכל ימי הארץ ימשך בה זרע וקציר וקור וחום וקיץ וחורף עד שישלם בזה מה שיצטרך להיות הצמחים ההווים בה ולב"ח ויום ולילה לא ישבותו שלא ימשך מהם בחלק הנגלה מהארץ התועלת אשר בעבורו נמצאו כמו שקדם בפרשת בראשי' וזה כולו להורות שלא יפסד זה החלק הנגלה מהארץ לעולם. וכבר בירך השם נח ובניו שיפרו וירבו וימלאו הארץ ר"ל שלא ישחת זרעם כמו שנשחת דור המבול אבל ימשך מהם מלא הארץ ר"ל שיתוסף זרעם עד שיתמלא הארץ ממנו. ואחר כן יתקיים על עניינו ולא יעתקו לעולם מהמלוא אל החסרון כמו שנעתקו בו בעת המבול וברכם ה' ית' ג"כ שיהיה מוראם על כל חית הארץ ועל כל עוף השמים ובכל אשר תרמוז האדמה ובכל דגי הים כי בידם נתנו לעשות כרצונם. ואולי הצטרכו לזאת הברכה לפי שהדורות הקודמים לרוע מנהגם היה השם מסתיר פניו מהם והיה אפשר שהיו חיות אוכלות בהם להיותם מטרה לחצי המקרים הרעים ולזה ברכם ה' ית' הברכה הזאת והנה התיר להם לאכול מכל הב"ח ואמ' להם שאין פשע להם בהריגתם אותם כי הם כירק עשב ביחס לאדם והם כולם נמצאים בעבור האדם ומנע אבר מן החי להיות בזה מרע המנהג ומהנטייה אל התאוות מה שלא יעלם ר"ל שלרוב הזוללות לא יוכל להמתין שתהרג הבהמה ויקח ממנה אחר כך האבר. ואמר להם שלא יחשבו מפני שהתיר להם הריגת הב"ח שיותר להם הריגתם קצת את קצת אבל יענשם הש' יתע' על זה וישים הפועל להגעת העונש להורג חבירו אחת מהחיות הטורפות ר"ל שתקום עליו ותהרגהו או יסבב שאחד מהאנשים יקום על ההורג ויהרגנו בשגגה וזה יותר נפלא כי אין טבע אישי המין להרוג קצתם את קצת כמו שימצא באישי המין האחד שיהרגו אישי מין אחר ויותר נפלא מזה שכבר ידרוש ה' ית' הדם מיד איש שהוא אחיו של שופך הדם וזה יהיה כשיסבב השם שיהרגנו בשגגה. וכל זה אמנם יהיה כשהרג שופך הדם ואין רואה אבל אם יש שם עדים הנה צוה אותם הש' יתע' שמי שישפך דם האדם ישפך דמו ע"י האדם מדת כנגד מדה וזה בלי ספק יהיה ע"י הדיינים והשופטים והם ישמען דברי העדים ויחקרו אם דבריהם אמתיים אם לא. ואמנם הסבה אשר חייבה שלא ישווה האדם בזה העניין לשאר הב"ח הוא היותו נברא בצלם אלהים מה שאין כן בשאר הב"ח ולזה יהרג הורגו והותרה הריגת הב"ח. וצוה אותם ג"כ שיפרו וירבו ר"ל שלא ישחיתו דרכם כמו שעשו אנשי דור המבול אבל יעשו זאת הפעולה לפרות ולרבות ולה נמנע מהם הזכור והבהמה ולא הוצרך להזהירם על הגזל ועל אשת איש לפי שכבר נתבאר לנח שאלו העבירות היו סבה אל שנשחת דורו במבול ולא הוצרך ג"כ להזהירם על ע"ז לזאת סבה בעינה כי אנשי דורו היו עובדים ע"ז כי כבר התחילו בזה מדור אנוש. ובעבור זה ג"כ קרה להם מה שקרה הנה הספיקו אלו המצות לבני נח לתקון קבוציהם לפי שכבר ידע הש' יתע' שלא יאות בהם בכללם שיקבלו מהשלמות יותר מזה. ואולם לבני ישראל צוה נימוס שלם להגיע אותם אל השלמות האנושי להיותם נונים להתנהג בו. ואחר כך אמר השם לנח ולבניו על ידו שכבר יקים בריתו עמם ועם זרעם אחריהם ועם כל מיני הב"ח שלא יכרתו עוד מימי המבול ולא יהיה עוד מבול לשחת הארץ. והנה בארנו במה שקדם עניין זה הברית מה הוא ר"ל שזה הברית היה ביום השביעי מימי הבריאה או היה עם נח ואם לא נזכר או יהיה זה הברית מה שאמר השם אל לבו שלא יוסיף עוד להכות כל חי כאשר עשה. ואמר להם הש"י שהו' נותן להם אות יתבאר להם בו שלא יהיה עוד מבול וזה שכבר נתן הש' טבע בעת בריאת העולם שירא' קשת בענן כשיהיו מימיו מועטים ויהיה ממנו הזלוף החלוש כמו שהתבאר בספר האותו'. ולזה היה הקשת הורא' על הפסק המטר כשירא' בהתחלה. ונהיו' העניין כן הנה יתאמת שלא יהיה מבול בהתהו' הענן פעם אחר פעם כשיראה בו הקשת כי אז יתאמת שלא יתכן שיהיה אז מבול אבל יפסק המטר או תמעט ירידתו. והנה גזר הש"י שאחר התחלת המטר זמן בלתי ארוך יראה קשת ויפסק המטר ההו' בבדר' שלא יהיה עוד מבול ולזה ראה ה' שיהיה הקשת אשר יראה תמיד בענן אות על הברית אשר בין הש"י ובין כל נפש חיה שלא יהיה עוד מבול לשחתם ולא יעברו עוד מי נח על האר'. וזה האות לא היה לנח לבד כדרך שאר האותות אבל שם אותו ה' ית' קיים בינו ובין כל נפש חיה אשר על הארץ ר"ל שתמיד יראה להם זה האות בעננו ענן והנה לא היה מציאות הקשת אות כי הוא נמצא על דרך הטבע אבל היה האות הראותו הש' ית' תמיד לנו בעננו ענו כמו שביארנו:
@78 **ויהיו בני נח היוצאים מן התיבה וגו'.**
@78 **ביאור דברי הספור:**
@78 **ספר** שמשלשלת בני נח נפצה הארץ והשתלשלו כל האומות כמו שיבאר אחר זה וספר עם זה שחם היה אבי כנען אשר היה בנו הקטן להיו' תכונתם מתדמה ברוע. וספר לנו עם זה אחד מהמקרים שקרו לנח להועילנו בזכירתו כמו העניין בשאר הספורים. ואמר שכבר התחל נח ליטע כרם לתכלית שיעשה ממנו יין כי חכם גדול היה בעבודת האדמה כמו שקדם. ולזה אמרו רז"ל בב"ר בו ביום נטע בו ביום שתה. ר"ל שהוא נטעו לזה התכלית והנה שתה מן היין יותר מן החוק הראוי והשיגהו השכרות עד שנרדם בתוך אהלו ונגלית ערותו וידמה לי שהיה כנען הוא המגלה ערות והנה ראה אח"כ חם אבי כנען את ערות אביו ולא בוש ולא כסה אותו אבל הגיד לשני אחיו בחוץ והם לצניעותם ולכבוד אביהם הפכו פניהם אחורנית ולקחו השמלה וכסו את ערות אביהם. וכאשר הקיץ נח מיינו ידע בנבואה אשר עשה לו בנו הקטן של חם והוא כנען והנה לא נתבארו מזה מה היה זה המעשה אבל עכ"פ ידענו שכבר היה מגונה מאד עד שקולל בעבורו כנען זאת הקללה הנפלאה אשר זכר והוא שיהיה כנען עובד אחיו עבדות נפלא. והנה אמר זה נח בנבואה ר"ל שכבר הגיע לו בנבואה שכנען הוא מקולל בזאת הקללה הנפלאה. והנה מה שאמרו ר"ל שסירס אותו הוא נאות מאד ולזה שלם לו נח מדה כנגד מדה כי כנען עשה זה שלא יוליד עוד נח בנים כדי שתהיה לו ולשאר בניו לבדם הארץ בדרך שלא ירבו המושלי' בה ונתמעט מפני זה חלק כנען וקולל מפני זה שיוסר ממנו הממשלה ויהיה עבד עבדים לאחיו. ואמר עוד ברוך יי' שהוא אלהי שם כי מזרעו תהיה האומה אשר נתיחדה לעבודת ה' והוא ישראל וזה יהיה סבה אל שתמשך הקללה לכנען שיעבוד זרע שם כי ישראל לקחו ארצו לאהבת ה' ית' אותם והשגחתו עליהם והיו הנשארים מהם עבדים לישראל ואם לא היה זרע שם בזה האופן משלמות שיהיה אלהיו אלהי שם לא הגיעה זאת הקללה לכנען. ואמר עוד ירחיב ה' ית' ליפת בסוף הימים וישכון באהלי שם וזה יהיה אחר ביאת מלך המשיח כהפוך הש' ית' שפה ברורה לעמים לקרא כולם בשם יי' ולעבדו שכם אחד. ואז יהיה כנען עובד לזרע יפת גם כן כי זרע כנען לחסרונו לא יכנע אז לעבודת ה' בהכנע שאר האמות ולזה תשיגהו זאת הקללה. וכבר אמר זה נח בדרך נבואה וספר אחר זה כמה היה נח אחר המבול. וכמה שנים חיה כמנהגו כשאר האנשים אשר השתלשלו מהם האבות הקדושים ר"ל אברהם יצחק ויעקב. הנה זה הביאור הוא הנראה לי בזאת הקללה והנמשך לה והוא הנאו' לאמת וללשון וכבר יצאנו בזה מספקות רבות יארך ספורם:
@90 **ואלה תולדות בני נח וגומ'. עד ויהי כל הארץ שפה אחת.**
@90 **ראוי** שתדע שכבר זכר בכאן תולדות יפת וחם ושם ושב לבאר בדרך קצרה איך השתלשלו מהם האומות המתחלפות ללשונותם וזהו התועלת המגיע מזה הספור כי בזה תתיישב בלבנו יותר אמונת החדוש כמו שקדם וזה אמנם היה אחר דור הפלגה ר"ל החלק אלו המשפחות ללשונות מתחלפים ואלה המשפחות היו נמצאות קודם זה ונתחדשו להם לשונות מתחלפים כמו שיתבאר בספרו שאחר זה ואח"כ שב לספר תולדו' שם בדרך ארוכה לפי שממנו השתלשלו האבו' הקדושים והנה ענין זה הספור מבואר:
@122 **אלה תולדות שם בן מאת שנה וגו':**
@122 **בעבור** שהיה הסתעפות האבות הקדושים משם שב לזכור תולדות שם בדרך ארוכה עד שהגיע לאבות וזכר עם זה בן כמה שנים היה כל אחד מהם כשהוליד וכמה שנים חיה אחר שהוליד לישב יותר בנפשותינו אמתת זה הספור הנבואיי והנה האריך בספור תולדות תרח. וזכר שהוא הוליד נחור ואברם והרן בעבור כבוד אברהם ובעבור מה שיספר ממנו בעבור האומו' אשר השתלשלו מהם כי מלוט בן הרן נסתעפו שתי אומות והם עמון ומואב וכבר ספר גם כן שאברהם צוה לתת לבנו אשה ממשפחתו והיא היתה מנחור וכן נשי יעקב ולזה הוכרח להזכיר נחור. וכבר הגיד ספורים רבים מענין אברהם עם לוט ולזה גם כן הוצרך להזכיר הרן אשר הוא אבי לוט. והאריך גם כן בספור ההוא ליישב יותר בנפשותינו אמתת זה הספור ולזה זכר המקום שמת בו הרן ושמות נשי אברם ונחור והמקום שיצא ממנו תרח עם אברהם ולוט והמקום שמת בו. ובכאן נשלם הביאור בזאת הפרשה:
@122 **אמר** שכל הארץ היתה מתחלת העניין אחר המבול שפה אחת ודברים אחרים ר"ל שהיו כלם בעלי לשון אחד וסדור דבריהם היה אחד ואמנם אמר זה לפי שכבר תמצא שהלשונות המתחלפים יתחלפו בשני אלו העניינים יחד עד שאם יועתק הלשון האחד אל האחר מלה מלה מזולת חלוף הסדור ישאר המאמר בלתי מובן וזה מבואר למי שיעתק מלשון הגרי ללשון הקדש וכן הענין בשאר הלשונות וידמה שזה הלשו' שהיו מדברים בו תחלה היה לשון הקוד' כי אדם דבר בלשון הקודש כמו שביארו בב"ר מאמרו לזאת יקרא אשה כי מאיש לוקחה זאת. ואמר שכבר נסעו ממזרח היישוב מצד שלא היה נכון המקום ההוא להוית הצמחי' להיות להם למזון כפי הראוי מצאו בקעה בארץ בכל נכונ' לעבוד ולזרוע ונתישבו שם. ואמרו איש אל רעהו שיעשו בנין גבוה מאד מלבנים וחומר בדרך שיהיה ארוך הקיום לפי שהלבנים לא ישחיתנו האש ולה המים ויגיעו להם בזה שתי תועלות לפי מחשבתם. האד לעשות להם שם. ר"ל שיקרא שמם על המגדל ההוא כשיאמר זה המגדל בנו אותו הראשונים המסתעפים מנח באופן הסתעפותם ממנו. ובזה ישאר זכר לראשונים. והשני שזה ישמרם שלא יפוצו על פני כל הארץ בבקשים מקומות נאותים לשכון בו להיות הות הצמחים ההכרחיי' שהם באדם כי הם יראו זה הבניין מרחוק לגבהו וישמרו שלא יתרחקו ממנו מרחק רב ובזה ישלם להן שיהיו כלם מקובצים במקום אחד מהארץ וזה יהיה גם כן בהוסיפם בבניין ההוא תמיד כל אשר יתוסף מספרם. ולפי שכבר ראה הש"י שהקבוץ לאדם במקום אחד מהארץ הוא בלתי נאות לקיום המין האנושי לפי שכבר אפשר שיקרה במקום מה מהארץ הפסד אם מצד הרעש וההפכה בהתהוות הרוח בבטן הארץ אם מצד הרוח החזק יפרק הרים וישבר סלעים אם מצד אבני אל גביש אם מצד שטף מים ומה שידמה לאללו הסבות המפסידות ואם היה המין האנושי כלו במקום אחד מהארץ היה אפשר בו שיפסד עם הפסד החלק ההוא מהארץ. ולזה היה מן ההכרחי לאדם שיהיה מפוזר בכל חלקי הישוב כדי שתתקיים מינו וכאשר יגיע ההפסד במקום אחד יתקיים המין בשאר. ולזה כבר הש' יתע' השתדל להפר עצתם ושם להם למשפחותיהם על דרך המופת תשוקה לחדש לשון ידברו בו המשפחה ההיא וכאשר נמשך העניין נשארו האחרונים בלתי מכירים בלשון זולת לשון משפחתם. וזה היה סבה שתסור ההסכמה מהמשפחות ההם ויפרדו מעל פני כל הארץ וחדלו להמשיך בניין העיר באופן אשר הסכימו בו והנה עשה זה הש"י להשגיח במין האנושי שישלם לו הקיום והוא מבואר של זה התכלית נעשה ואם לא נזכר לפי שהו' ממה שאין בו ספק שהש"י לא השתדל לבלבל הלשונות ללא תועלת ולהוסיף בנפשותינו אמתת זה הספור. ספר שזה היה סבה לקרא שם העיר בבל כי שם בלל יי' שפת כל הארץ ומשם הפיצם על פני כל הארץ. וראוי שתדע שנח ושם היו מבוני המגדל כי קודם שמת נח היו המשפחות מפוזרות בארץ לפי הנראה הלא תראה כי שש עשרה שנה אחר שמת נח צוה הש' יתע' לאברהם שיצא מארץ מולדתו וילך לארץ כנען:

@1 **ובכאן נשלם ביאור הספור הזה לפי הנראה לנו והנה התועלות המגיעות מזה הספור הם רבים:**
@1 **האחד** מהם להודיענו סודות השגחה האלהית באדם בפרטיו ובכלליו שהאמנה בהם מיישרת האדם לשלמותו מאד עם שעליה נבנית התורה בכללה. וזה שהוא העירנו במה שאמר לא ידון רוחי באדם שהמבול שהיה רע נפלא מאד היה להשגחה על המין האנושי שלא ימנע ממנו השלמות אשר בעבורו נברא כמו שקדם והעירנו במה שאמר כי אותך ראיתי צדיק לפני בדור הזה שהצדיק הוא מושגח מה' ית' השגחה נפלאה להצילו מהרעות נכונות לבא עליו כמו שהתבאר מהצלת נח והגנת הש' ית' בעדו בזה הספור הנפלא ואלו היה שם צדיק זולתו היה נצול עמו גם כן כמו שהתבאר ממה שנתנה התורה הסבה בהצלתו כי אותו ראה הש' ית' צדיק לפניו. ולזה יתחייב מזה שאם היה שם צדיק זולתו היה נצול עמו עד שאם יהיו הדור הוא שבים אל השם ועוזבים דרכיהם הרעים היו נצולים כולם ואע"פ שכבר ייעד להם הש' ית' זה הרע ביון קין באמרו שבעתים יוקם קין הנה חנון ה' וניחם על הרעה כמו שימצא במקומות רבים מדברי הנביאים ולזה הוא מבואר שלא היה כזה מהעדר דבר כי הם לא מתו בעון קין לבדו אך עונותיהם לכדום הלא תראה שגם זרע שת נמחה עמם כי לא נשאר רק נח ואלו שני המיני' שזכרנו מהשגחה הם החזקו' שבסבות לרע המגיע בכאן על צד ההשגחה האלהית ולטוב המגיע בכאן על צד ההשגחה האלהית. וכבר ביארנו מיני ההשגחה הזאת ועניינה והוסרו הספקו' הנופלות בה ועניינה ברביעי ממלחמו' יי' ובביאורינו לספר איוב ומשם יתבאר לך אמתת מה שהנחנו אותו בזה המקום:
@1 **התועלת** השני הוא שמה שביאר בכאן שהשם השחית הדור הרע הזה להשגחה על המין האנושי שלא ימנע ממנו שלמותו האיר עיני לבנו למצא הסבה אשר בעבורה נמצא זה האורך הנפלא מן החיים לאנשים ההם אשר העידה התורה שהיה מספר ימי חייהם זה המספר הנפלא כי זה אמנם היה לזאת הסבה בעינה כמו שביארנו במה שקדם:
@1 **התועלת** השלישי הוא במדות והוא שכבר הועילתנו התורה במה שספרה שנח היה בן חמש מאות שנה קודם שהוליד שהרפואה תהיה כמדו' הפחותות ההעתק אל הפכם מקצה אל קצה וזה שאנשי דור נח היו כלם שטופים בזמה עד שנשקעו בזה האופן המגונה אשר ספרה אותו התורה והוא נרפא מזאת המדה הפחות' כשנעתק אל הקצה האחרון מההתרחק מהמשגל עד שהיה בן שש מאות שנה קודם שהוליד:
@1 **התועלת** הרביעי והוא במדות והוא שכבר הועילתנו התורה תועלת נפלא במה שספרה מהצווי שצוה נח בעשיית התיבה בזה האופן השלם בדרך שישלם בה השמירה ובהכנסת המזונו' בה שיספיקו לו בהיותו בתיבה תועלת נפלא. והוא שגם האיש הצדיק אשר הוא מושגח מה' ית' אין ראוי שיתרשל מפני זה מהכנת הטרף לביתו ומהתנהג במנהג הטוב אשר ישלם בו בריאות הגוף כפי הראוי מפני בטחו בש"י כשיחשב שימצא לו מזונו ובריאותו וכ"ש ששאר האנשי' אין ראוי שיתרשלו בזה. אמרו ז"ל למען יברכך יי' אלהיך. יכול יושב בטל ת"ל בכל אשר תעשה:
@1 **התועלת** החמישי הוא במדות. והוא שאין ראוי לאדם שיתענג במיני התענוגים בעת היות שכניו בצער כי זה ממה שיפיל הקטטה והמחלוקת בין האנשים ויפסד בזה הקבוץ המדיני. וכבר העירתנו התורה על זה במה שזכרה שנח ובניו היו לבד ונשיהן לבד עד שמה שהולידו הולידו אחר המבול כמו שנזכר בתורה לא בהיותם בתיבה עם שכר היה זה סבה להם להתמיד דבקות ההשגחה האלהית כדי שתשלם להם ההצלחה כמו שביארנו.
@1 **התועלת** הששי והוא במדות. הוא שראוי לאדם שישגיח במי שהוא תחתיו מבני ביתו ומשרתיו לתת לו חוקו במה שיצטרך לעמיד' גופו וכבר העירתנו התורה בזה במה שהשגיחה בהמצאת מזונות הב"ח בתיבה וצואת נח שיזונם באמרו והיה לך ולהם לאכלה. כי זה ממה שיחייב שיכין להם נח מזונותיהם תמיד ואם זה ראוי בב"ח כ"ש שיהיה ראוי יותר בבני הבית והמשרתים והנה בזה האופן ישלים תקון קבוץ הבית אשר הוא התחלה לתקון קבוץ המדינה:
@1 **התועלת** השביעי והוא בדעות. הוא שכבר למדתנו התורה בזה הספור שהשם ית' כשיעשה המופתים אמנם יעשה אותם בסבות היותר נאותות לפי המנהג הטבעי. ולזה תמצא שבהוית מי המבול המציא הש"י בפליאה שתי סבות אשר היה יותר ראוי שישלם בהם זה והם רבוי הוית המים בבטן הארץ ורבוי הויתם בחלק האמצעי מן האויר ובחסרון המים הביא גם כן בפליאה הסבה היותה נאותה בזה והוא שהעביר ה' רוח על הארץ כי הרוח מדרכו שינגב וייבש כמו שהתבאר בספר האותות. ואולם היה זה כן לפי שהסדור הטבעי אשר לנמצאות שמחו השם יתע' ביותר שלם שבפנים שאפשר בו. וכאשר יביא ההכרח מצד ההשגחה לשנות זה הסדר הנה מן הראוי שיתרחק ממנו ה' ית' היותר מעט שאפשר ולזה לא עשה ה' ית' אלו המופתים כי אם בסבות שיהיה בהם יותר מעט מהזרות אצל הטבע ולא הביא המבול באמצעות הרוח וחסרון המים באמצעות המטר. וכזה בעינו תמצא מבואר בהרבה מהמופתים הנזכרים בתורה ובדברי הנביאים. וזה הפך ממה שיחשבו הסכלים מהמון אנשי תורתינו כי הם ישתדל לבאר דברי המופתים באופן שיהיה בו מן הזרות יותר אצל הטבע ויחשבו שזה הגדלה לשם יתעלה לא די שאינו הגדלה לשם ית' אבל הוא חסרון והם לא ישערו וזה מבואר מאד למעיין בזה הספ' עם מה שכבר ביארנוהו בזה העניין עד שהאריכות בביאורו הוא מותר:
@1 **התועלת** השמיני הוא בדעות. והוא שאי אפשר על המנהג הטבעי שיתהוה מן המינים הנולדים מימינם מזולת מינו כמו שהיה חושב אב"ן סי"נה שהיה אפשר שיהיה מבול מים בחלק הנגלה מהארץ ובאורך הזמן יתחדש מעירוב היסודות מה שיתהוה ממנו מין מהב"ח ולזה השתדל ה' יתע' כשרצה בקיום אלו המינים הנולדים מימינם שיושמו מהם זכר ונקבה בתיבה. והנה התועלת המגיע בעיון מזה הוא מבואר לפי שאם הונח הענין כן כמו שאמר אב"ן סי"נא תפול החכמה הטבעית בכללה וזה מבואר למי שעיין בטבעיות:
@1 **התועלת** התשיעי והוא בדעות והוא שאי אפשר שיפסד זה החלק הנגלה מהארץ אבל ימצאו בה תמיד אלו ההויו' אשר יתהוו בו ואין ראוי שתחשוב שיחוייב ממה שאמ' עוד כל ימי הארץ שיהיה לה עת תפסד בו שאם היה כן היה ג"כ אמרו כימי השמים על הארץ מורה על שיש עת לשמים. יפסדו בו וזה בטל לפי מה שביארנוהו בספר מ"י מהעיון והתורה ואולם אמר זה עוד כל ימי הארץ להורות על קיום זה הברית. ונצחותו כדרך מה שאמר עד בלתי שמים לא יקיצו שהרצון בו שלעולם לא יקיצו:
@1 **התועלת** העשירי הוא בדעות והוא שהקשת הוא מורה על מיעוט החלק המימיי בענן והוא סוד מסורות הטבע ואפשר שיהיו בכאן תועלות אחרות זולת אשר מנינו אלא שהתועלות אשר ראינו למנותם בכאן הם אלו ולהיות התועלות הנפלאות האלו מגיעות מזה הספור הרחיבה בו התורה הרחבה נפלאה לישב יותר אמתת זה הספור בנפשותינו:
@1 **וראוי** שנחקור בכאן בעניין הקרבנות שהקריב נח ושנשתדל להתיר ספר מה קרה בו אינו מעט וזה שכבר ביאר הרב המורה שענין הקרבנות אשר צווינו עליהם בתורה אינו מכוון בעצמו אבל הוא מכוון על הכוונה השנית להעתיקם ממה שהורגלו הדורות ההם לעשות כמו אלו העבודות לע"ז. ולזה אמר כי לא דברתי את אבותיכם ולא צויתים על דברי עולה וזבח. ואם היה הענין כן מה זה התעוררו הנביאי' לבנות מזבח ולהקריב עליו עולות כמו שמצינו העניין בנח. וכן מצינו באברהם במקומות רבים. וכן ביצחק וביעקב ובמשה. ומצאנו גם כן בכל עם כרצותו שתגיע אליו הנבואה צוה לבנות שבעה מזבחות ולערוך עליהם ז' פרים וז' אלים ויותר נפלא מזה שרבותינו הסכימו שהמזבחות כלם שעשו אותם הראשונים היו בהר המוריה במקום אשר נבנה שם בית המקדש ואם אמרנו שזה היה המכוון על הכונה השנית' היה יותר ראוי שיצוו אליה הנביאים לנמשכים אחריהם שיעשו אלו העבודות לש' ית' או שיביאו בני אדם לעשות אלו העבודות לש' ית' ונאמה שכבר יראה שבענין הקרבנות דבר מכוון על הכונה השנית ובהם עם זה דבר מכוון בעצמותו ומה שהוא מכוון בהם על הכונה השנית הם הרבה מהקרבנות אשר צוו ישראל עליהם ומה שהוא מכוון בהם על הכונה הראשונה לפי מה שיראה לי הם קצת העולות שהם כלי להגעת הנבואה כמו שנבאר בג"ה בזה המקום ובספר ויקרא. ולזה אמר בלעם לבלק אחר שהכין המזבחות והעלה פר ואיל במזבח התיצב כה על עולותיך ואלכה אולי יקרה יי' לקראתי. ולזה תמצא בהרבה מהמקומות אשר נזכר שם בניין המזבח הגעת הנבואה כמו הענין כמה שנזכר בכאן מנח. וכן תמצא באברהם וירא יי' אל אברם וגו'. ויבן שם מזבח. ויי' אמר אל אברם אחרי הפרד לוט מעמו וגו'. וסוף העניין. ויבן שם אברם מזבח. ואחר כן תמצא ויקרא אליו מלאך יי' מן השמים. וכן תמצא ביצחק וירא אליו יי' בלילה ההוא וגומ'. ויבן שם מזבח. וכן תמצא ביעקב ויבן שם מזבח ויקרא למקום ההוא אל בית אל כי שם נגלו אליו האלהים. ואח"כ אמר וירא אלהים אל יעקב. והנה יתבאר שיש לעניין הקרבנות מכא להגעת הנבואה ממה שאומר והוא שכבר יתבאר בשני ממלחמו' יי' שבעניין הנבואה יצטרך התבודדו' לשכל מבין שאר כחות הנפש ולזה לא ישלם כי אם בהתבטל שאר הכחות מפעולותיהם. ולזה יצטרך לנביא כשירצ' להתנבאת לעורר הכח השכלי וירדים שאר הכחות. ומפני זה תמצא בנביאים שהיו עושים פעולות להגי אליהם הנבואה כמאמר אלישע. ועתה קח לי מנגן והיה כנגן המנגן ותהי עליו יד יי'. והנ' תמצא בעניי הקרבנות שהם יעירו השכל וירדימו הכחות המרגישות וזה כי בזביחת הבעל חי ונתח אותו לנתחיו ושרוף אותו באש יש הכנע הנפש המרגשת מה שלא יעלם כי הכחו' המרגישו' כמו שיתעוררו מהרגשת המוחשים המתחדשים להם כך יכנעו וירדמו מהפסד המוחשים אשר אצלם הכנע מה שמפני זה יתן האדם אל לבו כי ההפסד הוא סוף כל אלו הדברים השפלים ותכנע מפני זה הנפש הבהמית ותדאג וירדמו כמותיה. וכבר יתעורר השכל כשיתבונן האדם בענין אלו הנתחים ואופן החכמה אשר ביצירתם בזה האופן שיראו בו ולהיות אלו הקרבנות מכוונים מהנביאים לזאת הכוונה היו עושים אותם במקום שהגיעה להם הנבואה להתמיד להם הנבואה שם כמו שהתבאר ממה שאמרנוהו מאברהם יצחק ויעקב והוא ביעקב יותר מבואר כי הוא ביאר שהוא בנה מזבח לפי ששם נגלו אליו האלהים. וכאשר היה מבואר לרז"ל שבית המקדש הוא המקום היותר מוכן לקבל כח עליון הנה החליטו המאמר מפני זה שהמזבחות אשר בנו הקודמים לש' ית' היה בהר המוריה. ובכאן הותר זה הספק והתבארה לנו סבה נפלאה בעניין הקרבנות ואולם השלמת המאמר בהם לפי אלו הסבות יהיה בג"ה במה שיבא אצל ביאור העניין בקרבנות:
@78 **והנה** התועלת הראשון המגיע מזאת הפרש' הוא במדו' שראוי להתרחק משתיית היין יותר מן החוק לפי שיקרה ממנו מן הגנות וההפסד מה שלא יעלם הלא תראה כי נח עם היותו שלם מאד נכשל בו. וכן ההקש בשאר הדברים המשכרים כמו החלב והדומה לו:
@78 **התועלת** השני הוא ג"כ במדות והוא שראוי שיתרחק האדם מהסתכל בעריות וכ"ש כשתהיה הערוה ההיא ערות ההורים כי בזה מהעזות יותר וזה אמנם יביא להמשך אחר המשגל ולזה תמצא בזרע כנען שהיו מתגאלים בעריות באופן אשר זכרה התורה מהם וכן בזרע מצרים כי הם היו בני חם גם כן אשר נשקע בזאת המדה הפחותה. ר"ל שהיה מסתכל בערות אביו ולהעיר על פחיתות זאת המדה והשלמות המגיע מהתרחק ממנה נתקלל כנען ונתברכו שם ויפת. והנה לא נתקל חם לפי ששאר בניו לא היו בזאת התכונה הפחותה ולזה לא היה מהיושר שתגיע הקללה להם זולתי בזרע כנען:
@78 **התועלת** הג' והוא בדעות. הוא שהברכת והקללות אשר יאמרו הנביאים שיגיעו לאנשים בדרך כולל. ר"ל שלא יבארו בזה זמן ומקום מיוחד הנה בהם בהכרח תנאי ואם לא נזכר והוא שאם היו האנשים ההם ראוים לברכה תמיד ימשך להם הברכה תמיד ואם לא לא תמשך בהם הברכה וכן הענין בקללה הלא תראה שכנען קולל שיהי עבד לאחיו והתפלל נח שיהיו שם ויפת ראוין אל שיגיע להם השירות מכנען והנה נשלים הסבה בזה בג"ה בפרשת וישלח יעקב:
@122 **והנה** התועלת המגיע מזה הספור הו' לישב בנפשותינו אמונת חדוש העולם ולהסיר הספק שאפשר שיסופק איך יתכן שיהיו מאב אחד לשונות מתחלפי' כמו שזכרנו בפרשת בראשית ונתן עם זה הסבה למה היתה מציאות הלשונות מתחלפים במין האנושי והוא להשגחה בו שישלם לו הקייום תמיד כמו שביארנו:
